window.LE_LABS = [{"id":"1.2.1-a","title":"Debian and Ubuntu: apt and dpkg","intro":"This lab system is Ubuntu-like, so software comes in `.deb` packages from repositories. `apt` (and the older `apt-get` and `apt-cache`) download and install them; `dpkg` is the low-level tool underneath.","setup":{},"commands":["apt-cache","apt","apt-get","sudo","figlet","dpkg"],"tasks":[{"text":"Search the package lists for `figlet` with apt-cache.","hints":["apt-cache search WORD"],"solution":"apt-cache search figlet","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*apt-cache\\s+search\\s+figlet"},{"type":"last","regex":"^figlet - "}]},"explain":"Searching never changes the system, so it doesn't need root."},{"text":"Search again with the newer `apt` command.","hints":["apt search WORD"],"solution":"apt search figlet","check":{"type":"last","regex":"figlet/noble"},"explain":"`apt` shows the repository and version, and marks installed packages."},{"text":"Install `figlet`.","hints":["Installing changes the system, so it needs root.","sudo apt-get install figlet (or sudo apt install figlet)"],"solution":"sudo apt-get install figlet","check":{"type":"exists","path":"/usr/bin/figlet","kind":"file"},"explain":"apt downloaded the package, resolved its dependencies (none here) and had dpkg unpack it.","mistakes":[{"cmd":"^\\s*apt(-get)?\\s+install","out":"are you root\\?","say":"Installing software changes the whole system, so it needs root: put `sudo` in front.","try":"apt-get install figlet"}]},{"text":"Run it: print `Hello` as a banner.","hints":["The program has the same name as the package."],"solution":"figlet Hello","check":{"type":"last","regex":"#"},"explain":"Package name and program name are often, but not always, the same."},{"text":"Ask dpkg whether `figlet` is installed.","hints":["dpkg -l NAME lists a package with its status."],"solution":"dpkg -l figlet","check":{"type":"last","regex":"\\nii\\s+figlet"},"explain":"`ii` means installed. `dpkg -L figlet` lists every file it installed."},{"text":"Remove `figlet` again.","hints":["sudo apt remove NAME"],"solution":"sudo apt remove figlet","check":{"type":"all","checks":[{"type":"absent","path":"/usr/bin/figlet"},{"type":"history","regex":"remove\\s+figlet"}]},"explain":"`remove` keeps configuration files in case you reinstall."},{"text":"Remove the printing system `cups` together with its configuration files.","hints":["purge removes configuration too."],"solution":"sudo apt purge cups","check":{"type":"all","checks":[{"type":"absent","path":"/etc/cups"},{"type":"history","regex":"purge\\s+cups"}]},"explain":"`purge` = remove + delete config. Check `ls /etc/cups` before and after."}],"obj":"1.2","lesson":"1.2.1","lessonTitle":"Installing software: apt, dpkg, dnf, yum and rpm","url":"https://learning.lpi.org/en/learning-materials/010-160/1/1.2/1.2_01/","part":1,"parts":2},{"id":"1.2.1-b","title":"Fedora and Red Hat: dnf, yum and rpm","intro":"This machine is Fedora-like: packages are `.rpm` files managed by `dnf` (`yum` on older systems, now a link to dnf) with `rpm` underneath. `apt` doesn't exist here.","setup":{"distro":"fedora"},"commands":["apt","yum","dnf","sudo","cowsay","rpm","grep"],"tasks":[{"text":"Try `apt search cowsay` and see what happens.","hints":["Just run it."],"solution":"apt search cowsay","check":{"type":"last","regex":"apt: command not found"},"explain":"Each distribution family has its own tools. Knowing both is on the exam."},{"text":"Search for a package matching `speaking cow` with yum.","hints":["yum search WORDS"],"solution":"yum search speaking cow","check":{"type":"last","regex":"cowsay"},"explain":"Search terms are matched against names and summaries."},{"text":"Install `cowsay` with dnf.","hints":["sudo dnf install NAME"],"solution":"sudo dnf install cowsay","check":{"type":"exists","path":"/usr/bin/cowsay","kind":"file"},"explain":"dnf asks for confirmation; `-y` answers yes, which is what scripts use.","mistakes":[{"cmd":"^\\s*dnf\\s+install","out":"superuser","say":"Installing needs root: `sudo dnf install cowsay`.","try":"dnf install cowsay"}]},{"text":"Make the cow say `Brought to you by dnf`.","hints":["cowsay TEXT"],"solution":"cowsay Brought to you by dnf","check":{"type":"last","regex":"Brought to you by dnf"},"explain":"Classic demo packages: harmless, small and fun."},{"text":"List every installed package with rpm and filter for cowsay.","hints":["rpm -qa lists everything; pipe into grep."],"solution":"rpm -qa | grep cowsay","check":{"type":"last","regex":"^cowsay-"},"explain":"`rpm -qi cowsay` shows details and `rpm -ql cowsay` its files."},{"text":"Remove cowsay with yum.","hints":["sudo yum remove NAME"],"solution":"sudo yum remove cowsay","check":{"type":"all","checks":[{"type":"absent","path":"/usr/bin/cowsay"},{"type":"history","regex":"yum\\s+remove\\s+cowsay"}]},"explain":"yum and dnf take the same commands."}],"obj":"1.2","lesson":"1.2.1","lessonTitle":"Installing software: apt, dpkg, dnf, yum and rpm","url":"https://learning.lpi.org/en/learning-materials/010-160/1/1.2/1.2_01/","part":2,"parts":2},{"id":"2.1.1-a","title":"Commands, options and arguments","intro":"Every command line is a **command**, then **options** (usually starting with `-`) that change how it behaves, then **arguments** it works on. You're logged in as `student`.","setup":{"files":[{"path":"~/notes.txt","data":"buy milk\ncall the ISP\nfinish lab 2.1\n"}]},"commands":["hostname","ls","cat"],"tasks":[{"text":"Print this computer's host name.","hints":["It's a one-word command, the same word as what you want to see."],"solution":"hostname","check":{"type":"last","regex":"^lab\\n$"},"explain":"The host name also appears in your prompt (student@**lab**). It's stored in `/etc/hostname`."},{"text":"List the contents of `/etc` in long format.","hints":["ls is the command, -l the option, /etc the argument."],"solution":"ls -l /etc","check":{"type":"history","regex":"^\\s*ls\\s+-\\w*l\\w*\\s+/etc/?\\s*$"},"explain":"`ls` = command, `-l` = option (long format: permissions, owner, size, date), `/etc` = argument. Most commands follow that order."},{"text":"List everything in your home directory, hidden files included, in long format. Combine the two short options into one.","hints":["The option for hidden files is -a and the long format is -l.","Short options can be glued together behind one dash."],"solution":"ls -al","check":{"type":"history","regex":"^\\s*ls\\s+-(al|la)\\w*\\s*(~|/home/student|\\.)?/?\\s*$"},"explain":"`ls -al`, `ls -la` and `ls -a -l` all mean the same. Files whose names start with a dot (like `.bashrc`) are hidden from a plain `ls`."},{"text":"Do the same again using only **long** options.","hints":["Long options use two dashes and a whole word.","The long form of -a is --all, and long format can be asked for with --format=long."],"solution":"ls --all --format=long","check":{"type":"all","checks":[{"type":"history","regex":"--all\\b"},{"type":"history","regex":"--format=long\\b"}]},"explain":"Long options are easier to read in scripts; short ones are quicker to type. GNU tools usually offer both."},{"text":"Show `notes.txt` with a number in front of every line.","hints":["cat prints files. It has an option for numbering lines."],"solution":"cat -n notes.txt","check":{"type":"last","regex":"^\\s+1\\tbuy milk\\n\\s+2\\t"},"explain":"`cat -n` numbers lines; `less -N` does the same in a pager. Handy when someone says 'look at line 12'."}],"obj":"2.1","lesson":"2.1.1","lessonTitle":"Command line basics: syntax, builtins and quoting","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_01/","part":1,"parts":4},{"id":"2.1.1-b","title":"Builtins and external commands","intro":"Some commands are built into the shell itself (**builtins**); others are separate programs on disk. `type` tells you which is which.","setup":{},"commands":["type"],"tasks":[{"text":"Ask the shell itself (not the manual) what kind of command `pwd` is: a builtin or a program on disk.","hints":["The command for this is in the intro above.","type NAME tells you how bash will run NAME."],"solution":"type pwd","check":{"type":"any","checks":[{"type":"last","regex":"pwd is a shell builtin"},{"type":"all","checks":[{"type":"history","regex":"^\\s*type\\s+-t\\s+pwd\\s*$"},{"type":"last","regex":"^builtin\\n$"}]}]},"explain":"`pwd` is a builtin: bash answers it itself without starting a program. (There's also a `/usr/bin/pwd`, but the builtin wins.)","mistakes":[{"cmd":"^\\s*(man|info)\\s+pwd\\b","say":"That's the manual page for the `pwd` program. It can't tell you how *this shell* runs the name. Ask the shell: `type pwd`.","try":"man pwd"},{"cmd":"^\\s*which\\s+pwd\\s*$","say":"`which` only searches the directories in `$PATH`, so it finds `/usr/bin/pwd`. But bash never runs that file: its builtin wins. Only `type` knows about builtins, so use `type pwd`.","try":"which pwd"}]},{"text":"Find out which file runs when you type `mv`.","hints":["The same command as the last task works for any name.","type mv, or which mv (which searches $PATH)."],"solution":"type mv","check":{"type":"any","checks":[{"type":"last","regex":"mv is /usr/bin/mv"},{"type":"all","checks":[{"type":"history","regex":"^\\s*which\\s+mv\\s*$"},{"type":"last","regex":"^/usr/bin/mv\\n$"}]}]},"explain":"External commands are files found by searching the directories in `$PATH`, in order. `type mv` and `which mv` both say `/usr/bin/mv`.","mistakes":[{"cmd":"^\\s*locate\\s+mv\\s*$","say":"`locate` lists every saved file name containing `mv`: on a real system that's a long list, and it doesn't say which one bash runs. Ask the shell: `type mv` (or `which mv`).","try":"locate mv"},{"cmd":"^\\s*find\\s+mv\\s*$","say":"`find` wants a starting directory first (`find / -name mv`) and searches the whole disk. To ask which file a command runs, use `type mv` or `which mv`.","try":"find mv"},{"cmd":"^\\s*where\\s+mv\\s*$","say":"`where` exists in zsh, not bash. In bash use `type mv` or `which mv`.","try":"where mv"}]},{"text":"Check `cd`, `cat` and `exit` with a single command.","hints":["type accepts several names at once."],"solution":"type cd cat exit","check":{"type":"all","checks":[{"type":"last","regex":"cd is a shell builtin"},{"type":"last","regex":"cat is /usr/bin/cat"},{"type":"last","regex":"exit is a shell builtin"}]},"explain":"`cd` and `exit` must be builtins: a separate program can't change the shell's current directory or end the shell. That's also why they have no man pages (try `help cd`)."},{"text":"Find out what `ll` really is.","hints":["It isn't a program or a builtin."],"solution":"type ll","check":{"type":"last","regex":"ll is aliased to"},"explain":"`ll` is an **alias** for `ls -l`, defined in `~/.bashrc`. Aliases are shortcuts that only exist inside the shell."}],"from":["basics"],"obj":"2.1","lesson":"2.1.1","lessonTitle":"Command line basics: syntax, builtins and quoting","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_01/","part":2,"parts":4},{"id":"2.1.1-c","title":"Quoting","intro":"Double quotes keep spaces together but still expand `$VARIABLES`. Single quotes keep everything literally. A backslash escapes one character.","setup":{},"commands":["echo","touch"],"tasks":[{"text":"Print the sentence `/home/student is my home directory`, using the HOME variable for the path.","hints":["Variables start with $. Put the whole sentence in double quotes."],"solution":"echo \"$HOME is my home directory\"","check":{"type":"last","regex":"^/home/student is my home directory\\n$"},"explain":"Inside double quotes `$HOME` is replaced by its value. Without quotes it works here too, but quotes keep spacing exactly as typed."},{"text":"Create an empty file named after your user name, using the USER variable.","hints":["touch creates empty files. $USER holds your login name."],"solution":"touch \"$USER\"","check":{"type":"exists","path":"/home/student/student","kind":"file"},"explain":"The shell expands `$USER` to `student` before touch runs, so touch only ever sees the word `student`."},{"text":"Create a file whose name is literally `$USER`, dollar sign included.","hints":["Stop the shell from expanding the variable.","Single quotes switch off every special character."],"solution":"touch '$USER'","check":{"type":"exists","path":"/home/student/$USER","kind":"file"},"explain":"Single quotes pass text through untouched. `\\$USER` (backslash) works too. Try `ls` to see both files."},{"text":"Create one file named `my notes.txt`, with the space in its name.","hints":["Without quotes the shell splits words at spaces."],"solution":"touch \"my notes.txt\"","check":{"type":"exists","path":"/home/student/my notes.txt","kind":"file"},"explain":"Quotes or a backslash (`my\\ notes.txt`) keep the space. You'll need them every time you use that name, which is why many people avoid spaces in file names.","mistakes":[{"cmd":"^\\s*touch\\s+my\\s+notes\\.txt\\s*$","say":"That created two files, `my` and `notes.txt`: the shell split the name at the space. Quote the name: `touch \"my notes.txt\"`.","try":"touch my notes.txt"}]}],"from":["basics"],"obj":"2.1","lesson":"2.1.1","lessonTitle":"Command line basics: syntax, builtins and quoting","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_01/","part":3,"parts":4},{"id":"2.1.1-d","title":"Brace expansion and wildcards","intro":"The shell rewrites some words before running a command: `{1..3}` and `{a,b}` expand into lists, and wildcards like `*` and `?` match existing file names.","setup":{"files":[{"path":"~/notes.txt","data":"draft\n"},{"path":"~/games.txt","data":"high scores\n"}]},"commands":["touch","mkdir","rm","pwd","mv"],"tasks":[{"text":"Create the files `game1` to `game5` with one `touch` command, without typing each name.","hints":["A range in braces like {1..5} expands to 1 2 3 4 5."],"solution":"touch game{1..5}","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/game1"},{"type":"exists","path":"/home/student/game2"},{"type":"exists","path":"/home/student/game3"},{"type":"exists","path":"/home/student/game4"},{"type":"exists","path":"/home/student/game5"},{"type":"history","regex":"\\{1\\.\\.5\\}"}]},"explain":"Run `echo game{1..5}` to see what the shell passes to the command. Brace expansion works for letters too: `{a..e}`."},{"text":"Create the directories `jan`, `feb` and `mar` with one `mkdir` and a brace list.","hints":["Braces can hold a comma-separated list."],"solution":"mkdir {jan,feb,mar}","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/jan","kind":"dir"},{"type":"exists","path":"/home/student/feb","kind":"dir"},{"type":"exists","path":"/home/student/mar","kind":"dir"},{"type":"history","regex":"\\{jan,feb,mar\\}|\\{\\w+,\\w+,\\w+\\}"}]},"explain":"Lists combine with text around them: `mkdir -p 2026/{jan,feb,mar}` makes three folders inside 2026."},{"text":"Delete all five game files with one `rm`, using the `?` wildcard. Keep `games.txt`.","hints":["? matches exactly one character.","game? matches game1 but not games.txt."],"solution":"rm game?","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/game1"},{"type":"absent","path":"/home/student/game2"},{"type":"absent","path":"/home/student/game3"},{"type":"absent","path":"/home/student/game4"},{"type":"absent","path":"/home/student/game5"},{"type":"exists","path":"/home/student/games.txt"},{"type":"history","regex":"\\brm\\b.*game\\?"}]},"explain":"`?` matches one character, `*` any number (even zero). `rm game*` would also have deleted `games.txt`, so `?` was the precise choice. Before deleting with a wildcard, `ls game?` shows what it matches.","mistakes":[{"cmd":"^\\s*(sudo\\s+)?rm\\s+(-\\w+\\s+)*game\\*","say":"`game*` also matched `games.txt`, so it's gone too. That's why the task asks for `?`, which matches exactly one character. Undo the last command and try again.","try":"rm game*"}]},{"text":"Show where you are, then move `notes.txt` into the `jan` directory here.","hints":["One command prints the working directory. mv moves files.","mv FILE DIRECTORY moves the file into the directory. jan is right here, so no leading slash."],"solution":"pwd\nmv notes.txt jan/","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/jan/notes.txt"},{"type":"history","regex":"^\\s*pwd\\s*$"}]},"explain":"When the last argument of `mv` is a directory, the file moves into it with the same name. `jan` and `jan/` both work; the trailing slash insists that `jan` is a directory, so a typo fails instead of quietly renaming the file. A leading slash (`/jan`) would mean a `jan` at the top of the filesystem.","mistakes":[{"cmd":"^\\s*(sudo\\s+)?mv\\s+notes\\.txt\\s+/jan/?\\s*$","say":"`/jan` starts with a slash, so it means a `jan` in the root directory `/`, not the `jan` folder here (`/home/student/jan`). Paths starting with `/` are absolute; paths without one start from where you are (`pwd`). Use `mv notes.txt jan/`.","try":"mv notes.txt /jan"}]}],"obj":"2.1","lesson":"2.1.1","lessonTitle":"Command line basics: syntax, builtins and quoting","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_01/","part":4,"parts":4},{"id":"2.1.2-a","title":"Shell variables","intro":"A variable is a name holding a value. Create one with `name=value` (no spaces around `=`) and read it with `$name`.","setup":{},"commands":["echo","unset"],"tasks":[{"text":"Create a variable named `number` holding `5`.","hints":["NAME=value, nothing else on the line."],"solution":"number=5","check":{"type":"var","name":"number","value":"5"},"explain":"No spaces: `number = 5` would run a command called `number` with the arguments `=` and `5`.","mistakes":[{"cmd":"^\\s*number\\s+=","say":"With spaces, bash thinks `number` is a command. Write it with no spaces: `number=5`.","try":"number = 5"}]},{"text":"Print its value.","hints":["Put a $ in front of the name."],"solution":"echo $number","check":{"type":"all","checks":[{"type":"last","regex":"^5\\n$"},{"type":"history","regex":"\\$\\{?number"}]},"explain":"`$number` and `${number}` are the same; braces help when text follows, as in `${number}th`."},{"text":"Delete the variable.","hints":["The builtin's name is the opposite of 'set'."],"solution":"unset number","check":{"type":"all","checks":[{"type":"novar","name":"number"},{"type":"history","regex":"^\\s*unset\\s+number\\s*$"}]},"explain":"After `unset`, `$number` expands to nothing. Note there's no `$` when you name the variable."}],"obj":"2.1","lesson":"2.1.2","lessonTitle":"Command line basics: variables","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_02/","part":1,"parts":4},{"id":"2.1.2-b","title":"Environment variables and child shells","intro":"A plain variable belongs to the current shell only. `export` turns it into an **environment variable**, which programs started from this shell receive a copy of.","setup":{},"commands":["export","bash","exit","env"],"tasks":[{"text":"Create an environment variable `ORDER` with the value `desc`.","hints":["export can set and export in one go."],"solution":"export ORDER=desc","check":{"type":"env","name":"ORDER","value":"desc"},"explain":"`export ORDER=desc` is short for `ORDER=desc` followed by `export ORDER`."},{"text":"Create a plain (not exported) variable `color` with the value `blue`.","hints":["Just NAME=value."],"solution":"color=blue","check":{"type":"all","checks":[{"type":"var","name":"color","value":"blue"},{"type":"env","name":"color","exported":false}]},"explain":"`set` lists every variable; `env` lists only the exported ones. Try both."},{"text":"Start a child shell.","hints":["The shell is a program too. Run it by name."],"solution":"bash","check":{"type":"shell","depth":1},"explain":"You're now in a second bash, started by the first. `$SHLVL` counts how deep you are."},{"text":"In the child shell, print both variables with one `echo`.","hints":["echo $color $ORDER"],"solution":"echo $color $ORDER","check":{"type":"all","checks":[{"type":"shell","depth":1},{"type":"last","regex":"^\\s*desc\\s*\\n$"}]},"explain":"Only `desc` appears: the child got a copy of exported `ORDER`, but `color` stayed behind in the parent."},{"text":"Go back to the parent shell.","hints":["The command that ends a shell."],"solution":"exit","check":{"type":"all","checks":[{"type":"shell","depth":0},{"type":"history","regex":"^\\s*exit\\s*$"}]},"explain":"Back in the first shell, `echo $color` works again: the variable never left this shell."},{"text":"Show only `ORDER` from the list of environment variables.","hints":["env prints the environment. Pipe it into a filter that keeps matching lines."],"solution":"env | grep ORDER","check":{"type":"last","regex":"^ORDER=desc\\n$"},"explain":"`env | grep NAME` is a quick way to check what a program will inherit. `printenv ORDER` prints just the value."}],"from":["basics"],"obj":"2.1","lesson":"2.1.2","lessonTitle":"Command line basics: variables","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_02/","part":2,"parts":4},{"id":"2.1.2-c","title":"bash -c and command substitution","intro":"`$(command)` runs a command and puts its output into the command line. Here a plain variable `color=blue` already exists.","setup":{"env":{"color":"blue"}},"commands":["bash","wc","export","date"],"tasks":[{"text":"Prove a child process can't see `color`: run `bash -c` with `echo [$color]` in single quotes.","hints":["bash -c 'commands' runs them in a new shell.","Single quotes stop THIS shell from expanding $color first."],"solution":"bash -c 'echo [$color]'","check":{"type":"last","regex":"^\\[\\]\\n$"},"explain":"With double quotes the parent would expand `$color` before bash -c ran, hiding the effect. Export it and try again to see `[blue]`."},{"text":"Store the number of lines in `/etc/passwd` in a variable `nr_users`, using command substitution.","hints":["wc -l counts lines. $( ) captures output.","wc -l FILE also prints the file name; redirect the file in with < to get just the number."],"solution":"nr_users=$(wc -l < /etc/passwd)","check":{"type":"var","name":"nr_users","value":"4"},"explain":"`/etc/passwd` has one line per account, so this counts accounts.","mistakes":[{"cmd":"wc\\s+-l\\s+/etc/passwd","say":"`wc -l /etc/passwd` prints the file name after the number, so the variable holds `4 /etc/passwd`. Use `wc -l < /etc/passwd`.","try":"nr_users=$(wc -l /etc/passwd)"}]},{"text":"Create an environment variable `ME` holding your user name, taken from `USER`.","hints":["export ME=$USER"],"solution":"export ME=$USER","check":{"type":"env","name":"ME","value":"student"},"explain":"Variables can be built from other variables; the shell expands `$USER` first."},{"text":"Append a colon and your home directory to `ME`, so it becomes `student:/home/student`.","hints":["Build the new value from the old: $ME, a colon, then $HOME."],"solution":"ME=$ME:$HOME","check":{"type":"var","name":"ME","value":"student:/home/student"},"explain":"This is exactly how directories are added to `PATH`: `PATH=$PATH:/new/dir`."},{"text":"Save today's date in UTC, formatted as YYYY-MM-DD, in a variable `today`.","hints":["date -u gives UTC. A +FORMAT argument chooses the fields; %F is YYYY-MM-DD."],"solution":"today=$(date -u +%F)","check":{"type":"var","name":"today","regex":"^\\d{4}-\\d{2}-\\d{2}$"},"explain":"Dated names like `backup-$(date +%F).tar.gz` sort correctly because the year comes first."},{"text":"Store the current date and time in New York in `ny`, setting `TZ` for that one command only.","hints":["NAME=value before a command sets a variable just for that command.","The zone is America/New_York."],"solution":"ny=$(TZ=America/New_York date)","check":{"type":"var","name":"ny","regex":"ED?T"},"explain":"`TZ=... date` changes the time zone only for that command; your shell's TZ is untouched."}],"obj":"2.1","lesson":"2.1.2","lessonTitle":"Command line basics: variables","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_02/","part":3,"parts":4},{"id":"2.1.2-d","title":"PATH","intro":"When you type a command name, the shell looks for a program with that name in each directory listed in `PATH`, left to right.","setup":{},"commands":["echo","which"],"tasks":[{"text":"Print your PATH.","hints":["It's a variable."],"solution":"echo $PATH","check":{"type":"last","regex":"/usr/bin"},"explain":"Directories are separated by colons. The first match wins, so order matters."},{"text":"Find which file runs when you type `date`.","hints":["One command searches PATH and prints the full path."],"solution":"which date","check":{"type":"last","regex":"^/usr/bin/date\\n$"},"explain":"`which` only looks at PATH; `type date` also knows about aliases and builtins."},{"text":"Create `~/bin` and add it to the END of your PATH without losing the existing directories.","hints":["mkdir ~/bin, then build PATH from its old value.","PATH=$PATH:~/bin"],"solution":"mkdir ~/bin\nPATH=$PATH:~/bin","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/bin","kind":"dir"},{"type":"var","name":"PATH","regex":"^/usr/local/sbin:.*/usr/bin.*:/home/student/bin$"}]},"explain":"Now any executable you put in `~/bin` runs by name. Add the line to `~/.bashrc` to keep it after you log out.","mistakes":[{"cmd":"^\\s*PATH=(~|/home/student)/bin\\s*$","say":"That replaced PATH with only ~/bin, so `ls` and friends are gone. Restore it with `PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin` and try again with `$PATH:` in front.","try":"PATH=~/bin"}]}],"from":["basics"],"obj":"2.1","lesson":"2.1.2","lessonTitle":"Command line basics: variables","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.1/2.1_02/","part":4,"parts":4},{"id":"2.2.1-a","title":"Manual pages","intro":"`man NAME` shows a command's manual. Pages live in numbered sections: 1 user commands, 5 file formats, 8 admin commands. On a real system press `q` to leave the pager.","setup":{},"commands":["man","whatis","apropos","help"],"tasks":[{"text":"Open the manual page for `ls`.","hints":["man followed by the command name."],"solution":"man ls","check":{"type":"history","regex":"^\\s*man\\s+(1\\s+)?ls\\s*$"},"explain":"Read NAME and SYNOPSIS first: `ls [OPTION]... [FILE]...` means options and files are optional and can repeat."},{"text":"Find out which manual sections have a page called `passwd`.","hints":["whatis (or man -f) prints the one-line description from every section."],"solution":"whatis passwd","check":{"type":"last","regex":"passwd \\(5\\)"},"explain":"Section 1 is the passwd command; section 5 describes the /etc/passwd file format."},{"text":"Read the page about the format of the /etc/passwd file.","hints":["Put the section number before the page name."],"solution":"man 5 passwd","check":{"type":"last","regex":"PASSWD\\(5\\)"},"explain":"Without the 5, man shows the first section it finds (1, the command)."},{"text":"Search every manual page description for the word `compress`.","hints":["apropos, or man with -k."],"solution":"apropos compress","check":{"type":"all","checks":[{"type":"last","regex":"gzip \\(1\\)"},{"type":"history","regex":"apropos|man\\s+-k"}]},"explain":"Use this when you know what you want to do but not the command's name."},{"text":"Ask for the man page of `cd`, then get help for it the right way.","hints":["cd is a builtin. Builtins are described by another builtin."],"solution":"man cd\nhelp cd","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*man\\s+cd\\s*$"},{"type":"last","regex":"^cd: cd \\[DIR\\]"}]},"explain":"Builtins have no man page of their own; `help NAME` describes them, and `man bash` has the full story."}],"obj":"2.2","lesson":"2.2.1","lessonTitle":"Getting help: man, info, locate and find","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.2/2.2_01/","part":1,"parts":4},{"id":"2.2.1-b","title":"info and --help","intro":"GNU tools keep their longest documentation in **info** documents, and almost every command prints a short summary with `--help`.","setup":{},"commands":["info","ls","cp"],"tasks":[{"text":"Open the info document for `ls`, find the menu entry about sorting, then list `/etc` sorted by modification time.","hints":["info ls, then look under 'Sorting the output'.","The option is -t."],"solution":"info ls\nls -t /etc","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*info\\s+ls\\s*$"},{"type":"history","regex":"^\\s*ls\\s+-\\w*t\\w*\\s+/etc/?\\s*$"}]},"explain":"In real info, Tab moves between links, Enter follows one, `u` goes up and `q` quits."},{"text":"Show the short usage summary of `cp`.","hints":["Most commands accept a long option named after what you want."],"solution":"cp --help","check":{"type":"last","regex":"^Usage: cp"},"explain":"`--help` is the fastest reminder when you just need an option name."},{"text":"Copy `/etc/hosts` to `~/hosts.copy`, keeping its permissions and timestamp. Find the option in cp's help.","hints":["Look for 'preserve' in the help.","It's -p."],"solution":"cp -p /etc/hosts ~/hosts.copy","check":{"type":"all","checks":[{"type":"sametime","path":"/home/student/hosts.copy","other":"/etc/hosts"},{"type":"history","regex":"^\\s*cp\\s+-\\w*[pa]"}]},"explain":"Without `-p` the copy gets the current time and you as owner. `cp -a` preserves everything and copies directories recursively."}],"from":["help"],"obj":"2.2","lesson":"2.2.1","lessonTitle":"Getting help: man, info, locate and find","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.2/2.2_01/","part":2,"parts":4},{"id":"2.2.1-c","title":"Finding files: locate and find","intro":"`locate` searches a database of file names (fast, but only as fresh as the last `updatedb`). `find` walks the disk itself (always current, slower).","setup":{},"commands":["locate","touch","updatedb","sudo","find"],"tasks":[{"text":"Show only the first three README files locate knows about.","hints":["locate has an option that limits the number of results."],"solution":"locate -l 3 README","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*locate\\s+(-l\\s*3|--limit[= ]3)\\s+README"},{"type":"last","regex":"README"}]},"explain":"Without a limit you could get thousands of lines on a real system."},{"text":"Create an empty file `test` in your home directory, then look for it with locate.","hints":["touch ~/test, then locate test."],"solution":"touch ~/test\nlocate /home/student/test","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/test"},{"type":"history","regex":"^\\s*locate\\s+\\S*test"}]},"explain":"Nothing found: the file is newer than locate's database."},{"text":"Rebuild locate's database and search again.","hints":["The command that updates it needs root."],"solution":"sudo updatedb\nlocate /home/student/test","check":{"type":"all","checks":[{"type":"located","path":"/home/student/test"},{"type":"last","regex":"/home/student/test"}]},"explain":"`updatedb` normally runs once a day. That's why locate can miss new files or list deleted ones (`locate -e` skips those).","mistakes":[{"cmd":"^\\s*updatedb\\s*$","out":"can not open","say":"updatedb writes a system-wide database, so it needs root: put `sudo` in front.","try":"updatedb"}]},{"text":"Find the same file with `find`, starting from your home directory.","hints":["find STARTDIR -name NAME"],"solution":"find ~ -name test","check":{"type":"last","regex":"/home/student/test\\n"},"explain":"find looks at the disk right now, so it doesn't need a database."},{"text":"Find every file under `/etc` whose name ends in `.conf`.","hints":["Use a wildcard pattern with -name, and quote it."],"solution":"find /etc -name '*.conf'","check":{"type":"all","checks":[{"type":"last","regex":"/etc/udev/udev\\.conf"},{"type":"last","regex":"/etc/resolv\\.conf"}]},"explain":"Quote the pattern so the shell passes `*.conf` to find instead of expanding it against files in the current directory."}],"obj":"2.2","lesson":"2.2.1","lessonTitle":"Getting help: man, info, locate and find","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.2/2.2_01/","part":3,"parts":4},{"id":"2.2.1-d","title":"Build a tree, search it, remove it","intro":"Practice the file commands you looked up: create a small tree, list it recursively, search it and delete it in one go.","setup":{},"commands":["mkdir","touch","ls","find","rm"],"tasks":[{"text":"Create `~/practice/docs` and `~/practice/src/lib` with one command.","hints":["mkdir needs an option to create missing parents."],"solution":"mkdir -p ~/practice/docs ~/practice/src/lib","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/practice/docs","kind":"dir"},{"type":"exists","path":"/home/student/practice/src/lib","kind":"dir"}]},"explain":"`-p` also makes mkdir quiet if a directory already exists, which is handy in scripts."},{"text":"Create the empty files `~/practice/docs/notes1`, `~/practice/src/main.c` and `~/practice/src/lib/util2.c`.","hints":["touch accepts several paths."],"solution":"touch ~/practice/docs/notes1 ~/practice/src/main.c ~/practice/src/lib/util2.c","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/practice/docs/notes1"},{"type":"exists","path":"/home/student/practice/src/main.c"},{"type":"exists","path":"/home/student/practice/src/lib/util2.c"}]},"explain":"touch creates any files that don't exist yet."},{"text":"List `~/practice` and all its subdirectories with one ls command.","hints":["ls has a recursive option (capital letter)."],"solution":"ls -R ~/practice","check":{"type":"last","regex":"/home/student/practice/src/lib:\\nutil2\\.c"},"explain":"`ls -R` prints each directory's name followed by its contents. `tree` (next lesson) draws the same as a picture."},{"text":"Find the files under `~/practice` whose names end in a digit.","hints":["A bracket expression [0-9] matches one digit."],"solution":"find ~/practice -name '*[0-9]'","check":{"type":"all","checks":[{"type":"last","regex":"notes1\\n"},{"type":"not","check":{"type":"last","regex":"main\\.c|util2\\.c"}}]},"explain":"`util2.c` ends in `c`, not a digit, so it doesn't match. The pattern must match the whole name."},{"text":"Remove `~/practice` and everything in it with one command.","hints":["rmdir only removes empty directories."],"solution":"rm -r ~/practice","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/practice"},{"type":"history","regex":"^\\s*rm\\s+-\\w*[rR]"}]},"explain":"`rm -r` deletes recursively and there's no trash can. Add `-i` to be asked about each file.","mistakes":[{"cmd":"^\\s*rmdir\\s","out":"not empty","say":"rmdir only removes empty directories. Use `rm -r` for a directory with contents.","try":"rmdir ~/practice"}]}],"obj":"2.2","lesson":"2.2.1","lessonTitle":"Getting help: man, info, locate and find","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.2/2.2_01/","part":4,"parts":4},{"id":"2.3.1-a","title":"Absolute and relative paths","intro":"An **absolute** path starts at `/` and works from anywhere. A **relative** path starts from where you are; `..` is the parent directory and `~` your home.","setup":{"users":[{"name":"michael"}],"files":[{"path":"~/Documents/reports","dir":true},{"path":"~/Downloads","dir":true},{"path":"/home/michael/Music","dir":true,"owner":"michael"}]},"commands":["pwd","cd","ls"],"tasks":[{"text":"Show which directory you are in.","hints":["Print working directory."],"solution":"pwd","check":{"type":"last","regex":"^/home/student\\n$"},"explain":"A new shell starts in your home directory, `/home/student`."},{"text":"Go to `/etc/udev` using an absolute path.","hints":["Absolute paths start with /."],"solution":"cd /etc/udev","check":{"type":"cwd","path":"/etc/udev"},"explain":"This works no matter where you start."},{"text":"List everything here, including the `.` and `..` entries.","hints":["ls has an 'all' option."],"solution":"ls -a","check":{"type":"all","checks":[{"type":"cwd","path":"/etc/udev"},{"type":"history","regex":"^\\s*ls\\s+-\\w*a"}]},"explain":"`.` is this directory and `..` its parent. Every directory has both."},{"text":"From here, go to the `Documents` directory in your home with the shortest command.","hints":["~ means your home directory."],"solution":"cd ~/Documents","check":{"type":"cwd","path":"/home/student/Documents"},"explain":"`~/Documents` is short for `/home/student/Documents`."},{"text":"Go up one level using a relative path.","hints":[".. is the parent."],"solution":"cd ..","check":{"type":"all","checks":[{"type":"cwd","path":"/home/student"},{"type":"history","regex":"^\\s*cd\\s+\\.\\./?\\s*$"}]},"explain":"From `/home/student/Documents`, `..` is `/home/student`."},{"text":"Go into the `Music` directory in michael's home directory with the shortest path.","hints":["~name means that user's home directory."],"solution":"cd ~michael/Music","check":{"type":"cwd","path":"/home/michael/Music"},"explain":"`~michael` expands to michael's home from `/etc/passwd`, wherever it is."},{"text":"Return to your home directory with the shortest possible command.","hints":["cd with no argument."],"solution":"cd","check":{"type":"all","checks":[{"type":"cwd","path":"/home/student"},{"type":"history","regex":"^\\s*cd\\s*$"}]},"explain":"`cd` alone goes home; `cd -` goes back to the previous directory."}],"from":["navigate"],"obj":"2.3","lesson":"2.3.1","lessonTitle":"Directories: absolute and relative paths","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.3/2.3_01/","part":1,"parts":2},{"id":"2.3.1-b","title":"Trees and awkward names","intro":"`tree` draws a directory hierarchy. Names with spaces need quotes or backslashes every time you use them.","setup":{"files":[{"path":"~/Documents/reports","dir":true},{"path":"~/Documents/reports/q3.txt","data":"x\n"},{"path":"~/Downloads","dir":true}]},"commands":["tree","mkdir","cd","rmdir"],"tasks":[{"text":"Show your home directory as a tree.","hints":["The command is named after the picture it draws."],"solution":"tree","check":{"type":"last","regex":"director(y|ies), \\d+ files?\\n$"},"explain":"tree isn't installed by default on most systems; the package is simply called `tree`."},{"text":"Show only the first level of the tree, with a `/` after directory names.","hints":["One option limits the depth (-L N); another classifies entries like ls -F."],"solution":"tree -L 1 -F","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*tree\\b.*-L\\s*1"},{"type":"history","regex":"^\\s*tree\\b.*-\\w*F"}]},"explain":"`-F` adds `/` to directories, `*` to executables and `@` to links."},{"text":"Create a directory named `this is a test`, spaces included.","hints":["Quote the name."],"solution":"mkdir \"this is a test\"","check":{"type":"exists","path":"/home/student/this is a test","kind":"dir"},"explain":"Without quotes you'd get four directories: this, is, a and test."},{"text":"Enter it by escaping each space with a backslash.","hints":["A backslash before a space makes it part of the name."],"solution":"cd this\\ is\\ a\\ test","check":{"type":"all","checks":[{"type":"cwd","path":"/home/student/this is a test"},{"type":"history","regex":"\\\\ "}]},"explain":"Tab completion writes these backslashes for you: type `cd this` and press Tab."},{"text":"Go back home and remove the empty directory with `rmdir`.","hints":["cd .. then rmdir with the name quoted."],"solution":"cd ..\nrmdir \"this is a test\"","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/this is a test"},{"type":"history","regex":"^\\s*rmdir\\s"}]},"explain":"rmdir refuses to delete non-empty directories, which makes it safe."}],"obj":"2.3","lesson":"2.3.1","lessonTitle":"Directories: absolute and relative paths","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.3/2.3_01/","part":2,"parts":2},{"id":"2.3.2-a","title":"Long listings and sorting","intro":"`~/pics` holds a few images of different sizes and ages. `ls -l` shows sizes and dates; other options sort by them.","setup":{"files":[{"path":"~/pics","dir":true},{"path":"~/pics/2025","dir":true,"mtime":"-40d"},{"path":"~/pics/2026","dir":true,"mtime":"-20d"},{"path":"~/pics/big.png","data":"","mtime":"-3d"},{"path":"~/pics/tiny.jpg","data":"JJJJJJJJJJ","mtime":"-30d"},{"path":"~/pics/mid.gif","data":"","mtime":"-1d"},{"path":"~/pics/notes.txt","data":"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn","mtime":"-10d"},{"path":"~/pics/2026/beach.png","data":""}]},"commands":["ls","cd"],"tasks":[{"text":"List `~/pics` in long format with human-readable sizes.","hints":["-l for long format, plus the option that turns 5000 into 4.9K."],"solution":"ls -lh ~/pics","check":{"type":"history","regex":"^\\s*ls\\s+-\\w*(lh|hl)\\w*\\s+(~|/home/student)/pics"},"explain":"Without `-h` sizes are in bytes."},{"text":"Go into `~/pics` and list only the directories in it.","hints":["The glob */ matches directories only. Stop ls from listing their contents.","ls -d */"],"solution":"cd ~/pics\nls -d */","check":{"type":"all","checks":[{"type":"cwd","path":"/home/student/pics"},{"type":"last","regex":"2025/\\s+2026/"}]},"explain":"`*/` makes the shell expand to directory names; `-d` lists those names instead of their contents."},{"text":"List the files sorted by size, largest first.","hints":["ls has a capital-letter option for size."],"solution":"ls -lS","check":{"type":"history","regex":"^\\s*ls\\s+-\\w*S"},"explain":"`-S` sorts by size; combine with `-h` for readable numbers."},{"text":"List them smallest first. Which file comes first?","hints":["Reverse the size sort."],"solution":"ls -lrS","check":{"type":"last","regex":"^total.*\\n\\S+.*tiny\\.jpg"},"explain":"`-r` reverses any sort order. `tiny.jpg` (10 bytes) is first."},{"text":"List them by modification time with the newest LAST.","hints":["-t sorts by time (newest first); reverse it."],"solution":"ls -lrt","check":{"type":"last","regex":"mid\\.gif\\n$"},"explain":"`ls -lrt` is a favourite for log directories: the most recently written file is right above your prompt."},{"text":"List them grouped by file extension.","hints":["A capital X."],"solution":"ls -lX","check":{"type":"history","regex":"^\\s*ls\\s+-\\w*X"},"explain":"Extensions don't matter to Linux itself, but sorting by them helps people."}],"obj":"2.3","lesson":"2.3.2","lessonTitle":"Listing files: long format, sorting, hidden files and sizes","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.3/2.3_02/","part":1,"parts":3},{"id":"2.3.2-b","title":"Hidden files, pagers and aliases","intro":"Files whose names start with `.` are hidden. Your home directory holds several configuration files like that.","setup":{"files":[{"path":"~/pics","dir":true},{"path":"~/pics/2025","dir":true,"mtime":"-40d"},{"path":"~/pics/2026","dir":true,"mtime":"-20d"},{"path":"~/pics/big.png","data":"","mtime":"-3d"},{"path":"~/pics/tiny.jpg","data":"JJJJJJJJJJ","mtime":"-30d"},{"path":"~/pics/mid.gif","data":"","mtime":"-1d"},{"path":"~/pics/notes.txt","data":"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn","mtime":"-10d"},{"path":"~/pics/2026/beach.png","data":""}]},"commands":["ls","less","alias","man"],"tasks":[{"text":"List all files in your home directory, including hidden ones.","hints":["ls -a"],"solution":"ls -a ~","check":{"type":"history","regex":"^\\s*ls\\s+-\\w*[aA]\\w*\\s+(~|/home/student)/?\\s*$"},"explain":"`.bashrc`, `.profile` and `.bash_logout` configure your shell. `-A` hides `.` and `..`."},{"text":"Read `~/.bashrc` in a pager.","hints":["less lets you scroll; q quits."],"solution":"less ~/.bashrc","check":{"type":"history","regex":"^\\s*less\\s+(~|/home/student)/\\.bashrc"},"explain":"In a real terminal, `/` searches inside less and `q` quits."},{"text":"Create an alias `lt` that runs `ls -lrt`.","hints":["alias NAME='command'"],"solution":"alias lt='ls -lrt'","check":{"type":"alias","name":"lt","value":"ls -lrt"},"explain":"Aliases last until the shell exits; put them in `~/.bashrc` to keep them."},{"text":"Use your new alias on `~/pics`.","hints":["Type the alias name like a command."],"solution":"lt ~/pics","check":{"type":"history","regex":"^\\s*lt\\b"},"explain":"The shell replaces `lt` with `ls -lrt` before running it."},{"text":"Ask for a manual page for `ll`.","hints":["man ll"],"solution":"man ll","check":{"type":"last","regex":"No manual entry for ll"},"explain":"Aliases aren't programs, so they have no man page. `type ll` explains what it is."}],"obj":"2.3","lesson":"2.3.2","lessonTitle":"Listing files: long format, sorting, hidden files and sizes","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.3/2.3_02/","part":2,"parts":3},{"id":"2.3.2-c","title":"How much space is used?","intro":"`ls -l` shows a directory's own size (its list of names), not what's inside. `du` adds up the contents.","setup":{"files":[{"path":"~/pics","dir":true},{"path":"~/pics/2025","dir":true,"mtime":"-40d"},{"path":"~/pics/2026","dir":true,"mtime":"-20d"},{"path":"~/pics/big.png","data":"","mtime":"-3d"},{"path":"~/pics/tiny.jpg","data":"JJJJJJJJJJ","mtime":"-30d"},{"path":"~/pics/mid.gif","data":"","mtime":"-1d"},{"path":"~/pics/notes.txt","data":"nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn","mtime":"-10d"},{"path":"~/pics/2026/beach.png","data":""}]},"commands":["ls","du"],"tasks":[{"text":"Show the size `ls` reports for the `~/pics` directory itself.","hints":["List the directory entry, not its contents."],"solution":"ls -ld ~/pics","check":{"type":"last","regex":"4096 .* (~|/home/student)/pics"},"explain":"4096 bytes is one block holding the directory's name list. It says nothing about the 9 KB of files inside."},{"text":"Show the disk usage of `~/pics` and its subdirectories in human-readable form.","hints":["du, with the same -h as ls."],"solution":"du -h ~/pics","check":{"type":"last","regex":"\\t/home/student/pics\\n$"},"explain":"du counts whole blocks, so even a 10-byte file uses 4 KiB."},{"text":"Show just the total for `~/pics`.","hints":["du has a 'summarize' option."],"solution":"du -sh ~/pics","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*du\\s+-\\w*s"},{"type":"last","regex":"^\\S+\\t/home/student/pics\\n$"}]},"explain":"`du -sh *` is a quick way to see which folder is filling the disk."},{"text":"List the contents of `~/pics` and every subdirectory with ls.","hints":["ls -R"],"solution":"ls -R ~/pics","check":{"type":"last","regex":"/home/student/pics/2026:\\nbeach\\.png"},"explain":"Recursive listings get long fast; `tree` or `find` are often easier to read."}],"obj":"2.3","lesson":"2.3.2","lessonTitle":"Listing files: long format, sorting, hidden files and sizes","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.3/2.3_02/","part":3,"parts":3},{"id":"2.4.1-a","title":"Making directories and files","intro":"Build a small project tree. `mkdir -p` creates parents, `touch` creates empty files, and `>` sends a command's output into a file.","setup":{},"commands":["mkdir","touch","echo","cat"],"tasks":[{"text":"Create `~/project/src/lib` and `~/project/docs` with one command.","hints":["mkdir -p accepts several paths."],"solution":"mkdir -p ~/project/src/lib ~/project/docs","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/project/src/lib","kind":"dir"},{"type":"exists","path":"/home/student/project/docs","kind":"dir"}]},"explain":"Without `-p`, mkdir fails because `~/project` doesn't exist yet.","mistakes":[{"cmd":"^\\s*mkdir\\s+(?!.*-\\w*p)","out":"No such file or directory","say":"The parent directories don't exist yet. Add `-p` so mkdir creates them.","try":"mkdir ~/project/src/lib"}]},{"text":"Create `~/project/tests/unit`, making mkdir report each directory it creates.","hints":["The verbose option is -v."],"solution":"mkdir -pv ~/project/tests/unit","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/project/tests/unit","kind":"dir"},{"type":"history","regex":"^\\s*mkdir\\s+-\\w*v"}]},"explain":"`-v` (verbose) is available on mkdir, cp, mv and rm."},{"text":"Create an empty file `~/project/README`.","hints":["touch"],"solution":"touch ~/project/README","check":{"type":"exists","path":"/home/student/project/README","kind":"file"},"explain":"On an existing file, touch only updates its timestamp."},{"text":"Write the line `Hello project` into `~/project/docs/intro.txt` using echo and redirection.","hints":["> sends output into a file (creating or overwriting it)."],"solution":"echo \"Hello project\" > ~/project/docs/intro.txt","check":{"type":"equals","path":"/home/student/project/docs/intro.txt","text":"Hello project\n"},"explain":"`>` overwrites; `>>` appends."},{"text":"Print the file to check it.","hints":["cat"],"solution":"cat ~/project/docs/intro.txt","check":{"type":"last","regex":"^Hello project\\n$"},"explain":"For longer files use `less`."}],"from":["files"],"obj":"2.4","lesson":"2.4.1","lessonTitle":"Creating, moving and deleting files","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.4/2.4_01/","part":1,"parts":4},{"id":"2.4.1-b","title":"Copying","intro":"You're in `~/project`. `cp SOURCE DEST` copies; with several sources the destination must be a directory.","setup":{"cwd":"~/project","files":[{"path":"~/project/docs/intro.txt","data":"Hello project\n"},{"path":"~/project/a.txt","data":"a\n"},{"path":"~/project/b.txt","data":"b\n"},{"path":"~/project/c.txt","data":"c\n"},{"path":"~/project/deploy.sh","data":"#!/bin/bash\necho deploy\n","mode":488,"mtime":"-10d"},{"path":"~/project/site/index.html","data":"new home\n","mtime":"-1d"},{"path":"~/project/site/about.html","data":"old about\n","mtime":"-9d"},{"path":"~/project/backup/index.html","data":"old home\n","mtime":"-5d"},{"path":"~/project/backup/about.html","data":"backup about\n","mtime":"-2d"}]},"commands":["cp"],"tasks":[{"text":"Copy `docs/intro.txt` to `docs/intro.bak`, showing what cp does.","hints":["-v"],"solution":"cp -v docs/intro.txt docs/intro.bak","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/project/docs/intro.bak"},{"type":"history","regex":"^\\s*cp\\s+-\\w*v"}]},"explain":"Verbose output is a good habit when copying many files."},{"text":"Try copying `a.txt` and `b.txt` onto `c.txt` (a file, not a directory). What happens?","hints":["cp a.txt b.txt c.txt"],"solution":"cp a.txt b.txt c.txt","check":{"type":"last","regex":"is not a directory"},"explain":"With more than two arguments, the last one must be a directory to copy into."},{"text":"Copy the whole `docs` directory to `docs-backup`.","hints":["Directories need the recursive option."],"solution":"cp -r docs docs-backup","check":{"type":"exists","path":"/home/student/project/docs-backup/intro.txt"},"explain":"`cp -a` would also preserve modes and timestamps.","mistakes":[{"cmd":"^\\s*cp\\s+docs\\s+docs-backup","out":"omitting directory","say":"cp skips directories unless you add `-r` (recursive).","try":"cp docs docs-backup"}]},{"text":"Copy `deploy.sh` to `deploy.copy`, keeping its timestamp (it was last changed 10 days ago).","hints":["The preserve option."],"solution":"cp -p deploy.sh deploy.copy","check":{"type":"sametime","path":"/home/student/project/deploy.copy","other":"/home/student/project/deploy.sh"},"explain":"Check with `ls -l`: both show the same date. Without `-p` the copy would be dated now."},{"text":"`site/` and `backup/` both have `index.html` and `about.html`. Copy `site/*` into `backup/` but only replace files that are older in backup.","hints":["cp has an 'update' option."],"solution":"cp -u site/* backup/","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/project/backup/index.html","text":"new home"},{"type":"contains","path":"/home/student/project/backup/about.html","text":"backup about"}]},"explain":"`index.html` was newer in site, so it was copied; `about.html` was newer in backup, so it was kept. `rsync` takes this idea much further."}],"obj":"2.4","lesson":"2.4.1","lessonTitle":"Creating, moving and deleting files","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.4/2.4_01/","part":2,"parts":4},{"id":"2.4.1-c","title":"Moving and renaming","intro":"`mv` both moves and renames. It overwrites existing files without asking unless you tell it not to.","setup":{"files":[{"path":"~/draft.txt","data":"text\n"},{"path":"~/archive","dir":true},{"path":"~/archive/notes.txt","data":"archived notes\n"},{"path":"~/notes.txt","data":"new notes\n"}]},"commands":["mv"],"tasks":[{"text":"Rename `draft.txt` to `final.txt`.","hints":["mv OLD NEW"],"solution":"mv draft.txt final.txt","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/final.txt"},{"type":"absent","path":"/home/student/draft.txt"}]},"explain":"Renaming is just moving within the same directory."},{"text":"Move `final.txt` into `archive/`, with mv reporting what it did.","hints":["-v"],"solution":"mv -v final.txt archive/","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/archive/final.txt"},{"type":"history","regex":"^\\s*mv\\s+-\\w*v"}]},"explain":"The trailing `/` makes it clear you mean the directory."},{"text":"Try moving `archive` into `archive/inside`.","hints":["mv archive archive/inside"],"solution":"mv archive archive/inside","check":{"type":"last","regex":"subdirectory of itself"},"explain":"A directory can't contain itself, so mv refuses."},{"text":"Move `notes.txt` into `archive/`, where a `notes.txt` already exists, WITHOUT overwriting it.","hints":["There's a 'no-clobber' option."],"solution":"mv -n notes.txt archive/","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/archive/notes.txt","text":"archived notes"},{"type":"exists","path":"/home/student/notes.txt"},{"type":"history","regex":"^\\s*mv\\s+(-\\w*n|--no-clobber)"}]},"explain":"`-n` never overwrites; `-i` asks first. Plain mv would have silently replaced the archived copy.","mistakes":[{"cmd":"^\\s*mv\\s+notes\\.txt\\s+archive/?\\s*$","say":"Plain mv replaced archive/notes.txt without asking: the archived text is gone. That's why `-n` (or `-i`) exists. Restart the part to try again.","try":"mv notes.txt archive/"}]}],"obj":"2.4","lesson":"2.4.1","lessonTitle":"Creating, moving and deleting files","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.4/2.4_01/","part":3,"parts":4},{"id":"2.4.1-d","title":"Deleting and globs","intro":"Wildcards (globs) select files by pattern: `*` any characters, `?` exactly one, `[a-z]` one from a set. Look before you delete: run `ls PATTERN` first.","setup":{"files":[{"path":"~/old1.log","data":""},{"path":"~/old2.log","data":""},{"path":"~/oldnotes","data":""},{"path":"~/keep.txt","data":"keep\n"},{"path":"~/log_a_2019_jan_01.txt","data":""},{"path":"~/log_b_2018_feb_01.txt","data":""},{"path":"~/log_C_2019_x_01.txt","data":""},{"path":"~/log_c_2020_mar_01.txt","data":""},{"path":"~/log_d_2017_apr_02.txt","data":""},{"path":"~/doc100","data":""},{"path":"~/doc200","data":""},{"path":"~/doc301","data":""},{"path":"~/doc401","data":""},{"path":"~/doc402","data":""},{"path":"~/doc999","data":""},{"path":"~/a/b/c","dir":true},{"path":"~/trash/x.tmp","data":""},{"path":"~/trash/y.tmp","data":""},{"path":"~/trash/sub/z.tmp","data":""}]},"commands":["rm","ls","rmdir"],"tasks":[{"text":"Delete every file whose name starts with `old`, keeping `keep.txt`.","hints":["old* matches oldnotes, old1.log, ..."],"solution":"rm old*","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/old1.log"},{"type":"absent","path":"/home/student/old2.log"},{"type":"absent","path":"/home/student/oldnotes"},{"type":"exists","path":"/home/student/keep.txt"}]},"explain":"Safety tip: `ls old*` first shows exactly what `rm old*` will delete."},{"text":"List the files matching `log_[a-z]_201?_*_01.txt`.","hints":["Just ls the pattern exactly as given."],"solution":"ls log_[a-z]_201?_*_01.txt","check":{"type":"all","checks":[{"type":"last","regex":"log_a_2019_jan_01\\.txt"},{"type":"last","regex":"log_b_2018_feb_01\\.txt"},{"type":"not","check":{"type":"last","regex":"log_C|log_c_2020|_02\\.txt"}}]},"explain":"`[a-z]` is one lowercase letter (not C), `201?` is 2010-2019, `*` anything, and `_01` must match exactly."},{"text":"Delete `doc100`, `doc200`, `doc301` and `doc401` with one glob, keeping `doc402` and `doc999`.","hints":["They are doc, a digit 1-4, a 0, then 0 or 1.","doc[1-4]0[01]"],"solution":"rm doc[1-4]0[01]","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/doc100"},{"type":"absent","path":"/home/student/doc200"},{"type":"absent","path":"/home/student/doc301"},{"type":"absent","path":"/home/student/doc401"},{"type":"exists","path":"/home/student/doc402"},{"type":"exists","path":"/home/student/doc999"}]},"explain":"Each bracket matches exactly one character from its set."},{"text":"Remove the empty directories `a/b/c`, then `a/b`, then `a`, with one rmdir command.","hints":["rmdir has an option to remove parents too."],"solution":"rmdir -p a/b/c","check":{"type":"absent","path":"/home/student/a"},"explain":"`rmdir -p` stops at the first directory that isn't empty, so it can't delete anything by accident."},{"text":"Remove `trash/` and everything in it, listing each file as it goes.","hints":["Recursive plus verbose."],"solution":"rm -rv trash","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/trash"},{"type":"history","regex":"^\\s*rm\\s+-\\w*[rR]\\w*v|^\\s*rm\\s+-\\w*v\\w*[rR]"}]},"explain":"Use `rm -ri` to be asked about each file instead; there's no undo."}],"obj":"2.4","lesson":"2.4.1","lessonTitle":"Creating, moving and deleting files","url":"https://learning.lpi.org/en/learning-materials/010-160/2/2.4/2.4_01/","part":4,"parts":4},{"id":"3.1.1-a","title":"Compressing single files","intro":"gzip, bzip2 and xz each compress ONE file and replace it with a compressed copy (`.gz`, `.bz2`, `.xz`). Roughly: gzip is fastest, xz makes the smallest files.","setup":{"files":[{"path":"~/big.log","data":"09:00 start\n09:01 tick\n09:02 tick\n09:03 tick\n09:04 tick\n09:05 tick\n09:06 tick\n09:07 tick\n09:08 tick\n09:09 tick\n09:10 tick\n09:11 tick\n09:12 tick\n09:13 tick\n09:14 tick\n09:15 tick\n09:16 tick\n09:17 tick\n09:18 tick\n09:19 tick\n09:20 tick\n09:21 tick\n09:22 tick\n09:23 tick\n09:24 tick\n09:25 tick\n09:26 tick\n09:27 tick\n09:28 tick\n09:29 tick\n09:30 tick\n09:31 tick\n09:32 tick\n09:33 tick\n09:34 tick\n09:35 tick\n09:36 tick\n09:37 tick\n09:38 tick\n09:39 tick\n"},{"path":"~/notes.txt","data":"remember the milk\n"},{"path":"~/data.csv","data":"id,name\n0,item0\n1,item1\n2,item2\n3,item3\n4,item4\n5,item5\n6,item6\n7,item7\n8,item8\n9,item9\n10,item10\n11,item11\n12,item12\n13,item13\n14,item14\n15,item15\n16,item16\n17,item17\n18,item18\n19,item19\n20,item20\n21,item21\n22,item22\n23,item23\n24,item24\n25,item25\n26,item26\n27,item27\n28,item28\n29,item29\n30,item30\n31,item31\n32,item32\n33,item33\n34,item34\n35,item35\n36,item36\n37,item37\n38,item38\n39,item39\n40,item40\n41,item41\n42,item42\n43,item43\n44,item44\n45,item45\n46,item46\n47,item47\n48,item48\n49,item49\n"}]},"commands":["gzip","zcat","gunzip","bzip2","bunzip2","xz","unxz"],"tasks":[{"text":"Compress `big.log` with gzip.","hints":["gzip FILE"],"solution":"gzip big.log","check":{"type":"all","checks":[{"type":"compressed","path":"/home/student/big.log.gz","kind":"gzip"},{"type":"absent","path":"/home/student/big.log"}]},"explain":"The original is replaced by `big.log.gz`. Use `gzip -k` to keep the original too."},{"text":"Show the first three lines of the compressed file without decompressing it to disk.","hints":["zcat prints compressed data; pipe it into head."],"solution":"zcat big.log.gz | head -n 3","check":{"type":"last","regex":"^09:00 start\\n09:01 tick\\n09:02 tick\\n$"},"explain":"`zcat`, `bzcat` and `xzcat` are handy for old rotated logs (`syslog.2.gz`)."},{"text":"Decompress it again.","hints":["gunzip, or gzip -d."],"solution":"gunzip big.log.gz","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/big.log","kind":"file"},{"type":"absent","path":"/home/student/big.log.gz"},{"type":"history","regex":"^\\s*(gunzip|gzip\\s+-d)"}]},"explain":"The format includes a checksum, so a damaged file is reported instead of silently giving you corrupt data."},{"text":"Compress `notes.txt` with bzip2, then decompress it with bunzip2.","hints":["bzip2 FILE, then bunzip2 FILE.bz2"],"solution":"bzip2 notes.txt\nbunzip2 notes.txt.bz2","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/notes.txt"},{"type":"history","regex":"^\\s*bzip2\\s"},{"type":"history","regex":"^\\s*bunzip2\\s|bzip2\\s+-d"}]},"explain":"bzip2 usually compresses text better than gzip but is slower."},{"text":"Compress `data.csv` with xz at its strongest setting.","hints":["Compression levels are given as -1 to -9."],"solution":"xz -9 data.csv","check":{"type":"all","checks":[{"type":"compressed","path":"/home/student/data.csv.xz","kind":"xz"},{"type":"history","regex":"^\\s*xz\\s+-\\w*9"}]},"explain":"Higher levels trade time (and memory) for size. The default is 6."},{"text":"Decompress `data.csv.xz`.","hints":["unxz, or xz -d."],"solution":"unxz data.csv.xz","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/data.csv","kind":"file"},{"type":"absent","path":"/home/student/data.csv.xz"},{"type":"history","regex":"^\\s*(unxz|xz\\s+-d)"}]},"explain":"unxz is the same as `xz -d`."}],"obj":"3.1","lesson":"3.1.1","lessonTitle":"Archiving and compression: tar, gzip, bzip2, xz and zip","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.1/3.1_01/","part":1,"parts":4},{"id":"3.1.1-b","title":"tar archives","intro":"tar bundles many files and directories into one archive, keeping names and permissions. The options say what to do: `c` create, `t` list, `x` extract, `r` append, and `f` names the archive file.","setup":{"files":[{"path":"~/site/index.html","data":"<h1>Welcome</h1>\n"},{"path":"~/site/css/style.css","data":"body{margin:0}\n"},{"path":"~/site/img/logo.png","data":""}]},"commands":["tar","touch","mkdir"],"tasks":[{"text":"Create `site.tar` from the `site` directory, listing files as they're added.","hints":["c to create, v verbose, f for the file name (last, right before the name)."],"solution":"tar -cvf site.tar site","check":{"type":"archive","path":"/home/student/site.tar","format":"tar","compression":null,"has":["site/index.html","site/css/style.css"]},"explain":"`-f` takes the next word as the archive name, so it goes last in the group: `-cvf site.tar`, not `-cfv`."},{"text":"List the archive's contents with details.","hints":["t to list, plus v and f."],"solution":"tar -tvf site.tar","check":{"type":"last","regex":"site/css/style\\.css"},"explain":"Always list an archive from someone else before extracting it."},{"text":"Create `site/about.html`, then add it to `site.tar` without rebuilding the archive.","hints":["touch it, then tar's append option is r."],"solution":"touch site/about.html\ntar -rf site.tar site/about.html","check":{"type":"archive","path":"/home/student/site.tar","format":"tar","has":["site/about.html"]},"explain":"`-r` appends and `-u` appends only files newer than the archived copies. Neither works on a compressed archive."},{"text":"Extract `site.tar` into a new directory `~/restore`.","hints":["Create the directory, then -C tells tar where to extract."],"solution":"mkdir ~/restore\ntar -xf site.tar -C ~/restore","check":{"type":"contains","path":"/home/student/restore/site/index.html","text":"Welcome"},"explain":"Without `-C`, tar extracts into the current directory."},{"text":"Archive `/etc/hosts` into `hosts.tar`, keeping the leading `/` in the member name.","hints":["tar normally strips the leading / for safety. One option keeps absolute names."],"solution":"tar -cPf hosts.tar /etc/hosts","check":{"type":"archive","path":"/home/student/hosts.tar","format":"tar","has":["/etc/hosts"]},"explain":"Stripping `/` is a safety feature: extracting `/etc/hosts` as root would overwrite the real file. Use `-P` only when you mean it."}],"from":["archives"],"obj":"3.1","lesson":"3.1.1","lessonTitle":"Archiving and compression: tar, gzip, bzip2, xz and zip","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.1/3.1_01/","part":2,"parts":4},{"id":"3.1.1-c","title":"Compressed archives","intro":"Add a compression option to tar: `z` gzip (.tar.gz/.tgz), `j` bzip2 (.tar.bz2), `J` xz (.tar.xz). A gzip archive `site.tar.gz` is ready for you.","setup":{"files":[{"path":"~/site/index.html","data":"<h1>Welcome</h1>\n"},{"path":"~/site/css/style.css","data":"body{margin:0}\n"},{"path":"~/site/img/logo.png","data":""}],"run":["tar -czf site.tar.gz site"]},"commands":["tar","gunzip"],"tasks":[{"text":"Create `site.tar.bz2` from `site`.","hints":["c, j for bzip2, f."],"solution":"tar -cjf site.tar.bz2 site","check":{"type":"archive","path":"/home/student/site.tar.bz2","compression":"bzip2","format":"tar","has":["site/index.html"]},"explain":"Same command as before plus `j`."},{"text":"Create `site.tar.xz` from `site`.","hints":["Capital J is xz."],"solution":"tar -cJf site.tar.xz site","check":{"type":"archive","path":"/home/student/site.tar.xz","compression":"xz","format":"tar","has":["site/index.html"]},"explain":"Kernel source releases are distributed as .tar.xz."},{"text":"List only the `.css` files inside `site.tar.gz`, using a wildcard.","hints":["List with tzf, then give a pattern. tar needs to be told the name is a pattern."],"solution":"tar -tzf site.tar.gz --wildcards '*.css'","check":{"type":"all","checks":[{"type":"last","regex":"site/css/style\\.css"},{"type":"not","check":{"type":"last","regex":"index\\.html"}}]},"explain":"Quote the pattern so the shell doesn't expand it, and add `--wildcards` so tar treats it as one.","mistakes":[{"cmd":"tar\\s+-?t\\w*\\s+site\\.tar\\.gz\\s+'?\\*\\.css'?\\s*$","out":"Not found in archive","say":"tar matches member names literally by default. Add `--wildcards`.","try":"tar -tzf site.tar.gz '*.css'"}]},{"text":"Extract `site.tar.gz` into `~/out` WITHOUT tar's `z` option: decompress it first, then extract.","hints":["gunzip turns site.tar.gz into site.tar.","Then tar -xf site.tar -C ~/out (create ~/out first)."],"solution":"gunzip site.tar.gz\nmkdir ~/out\ntar -xf site.tar -C ~/out","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/out/site/index.html","text":"Welcome"},{"type":"history","regex":"^\\s*gunzip\\s"}]},"explain":"This is what `tar -xzf` does in one step. Current GNU tar even detects the compression itself, so `tar -xf site.tar.gz` also works."}],"obj":"3.1","lesson":"3.1.1","lessonTitle":"Archiving and compression: tar, gzip, bzip2, xz and zip","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.1/3.1_01/","part":3,"parts":4},{"id":"3.1.1-d","title":"zip","intro":"zip bundles and compresses in one step, in the format Windows and macOS open natively. Unlike gzip, it keeps the original files.","setup":{"files":[{"path":"~/site/index.html","data":"<h1>Welcome</h1>\n"},{"path":"~/site/css/style.css","data":"body{margin:0}\n"},{"path":"~/site/img/logo.png","data":""}]},"commands":["zip","unzip"],"tasks":[{"text":"Create `site.zip` containing the `site` directory and everything in it.","hints":["zip needs its recursive option for directories."],"solution":"zip -r site.zip site","check":{"type":"archive","path":"/home/student/site.zip","format":"zip","has":["site/css/style.css"]},"explain":"Without `-r` zip would only store the empty `site/` entry.","mistakes":[{"cmd":"^\\s*zip\\s+site\\.zip\\s+site/?\\s*$","say":"That only stored the directory entry, not the files inside. Add `-r`.","try":"zip site.zip site"}]},{"text":"List the contents of `site.zip`.","hints":["unzip has a list option."],"solution":"unzip -l site.zip","check":{"type":"last","regex":"site/css/style\\.css"},"explain":"Same idea as `tar -t`."},{"text":"Create `stored.zip` from `site` with no compression at all.","hints":["Levels go from -0 (store only) to -9."],"solution":"zip -0r stored.zip site","check":{"type":"all","checks":[{"type":"archive","path":"/home/student/stored.zip","format":"zip","has":["site/index.html"]},{"type":"history","regex":"^\\s*zip\\s+(-\\w*0|.*\\s-0)"}]},"explain":"Storing is useful for files that are already compressed, like JPEGs or other zips."},{"text":"Extract `site.zip` into `~/unzipped`.","hints":["unzip has an option for the target directory."],"solution":"unzip site.zip -d ~/unzipped","check":{"type":"contains","path":"/home/student/unzipped/site/index.html","text":"Welcome"},"explain":"unzip creates the target directory if needed."}],"from":["archives"],"obj":"3.1","lesson":"3.1.1","lessonTitle":"Archiving and compression: tar, gzip, bzip2, xz and zip","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.1/3.1_01/","part":4,"parts":4},{"id":"3.2.1-a","title":"Redirecting output and errors","intro":"Every program has standard output (1) and standard error (2). `>` sends output to a file (overwriting), `>>` appends, `2>` sends errors, `&>` sends both.","setup":{"files":[{"path":"~/server.log","data":"10:00 ERROR disk\n10:01 ok\n10:02 ok\n10:03 ok\n10:04 ok\n10:05 ok\n10:06 ok\n10:07 ERROR disk\n10:08 ok\n10:09 ok\n10:10 ok\n10:11 ok\n10:12 ok\n10:13 ok\n10:14 ERROR disk\n10:15 ok\n10:16 ok\n10:17 ok\n10:18 ok\n10:19 ok\n10:20 ok\n10:21 ERROR disk\n10:22 ok\n10:23 ok\n10:24 ok\n10:25 ok\n10:26 ok\n10:27 ok\n10:28 ERROR disk\n10:29 ok\n"}]},"commands":["ls","sort","tail","date"],"tasks":[{"text":"Save a long listing of your home directory in `contents.txt`.","hints":["ls -l, then > and a file name."],"solution":"ls -l ~ > contents.txt","check":{"type":"contains","path":"/home/student/contents.txt","regex":"^total","flags":"m"},"explain":"The listing goes into the file instead of the screen."},{"text":"Append a sorted copy of `contents.txt` to `contents-sorted.txt`.","hints":[">> appends."],"solution":"sort contents.txt >> contents-sorted.txt","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/contents-sorted.txt","regex":"server\\.log"},{"type":"history","regex":">>\\s*contents-sorted\\.txt"}]},"explain":"Run it twice and the file has two copies: `>>` never deletes what's there."},{"text":"Save the last 10 lines of `server.log` in `last10.txt`.","hints":["tail -n 10"],"solution":"tail -n 10 server.log > last10.txt","check":{"type":"lines","path":"/home/student/last10.txt","count":10},"explain":"`tail` without `-n` also shows 10 lines; being explicit is clearer."},{"text":"Append the current date to `last10.txt`.","hints":["date >> file"],"solution":"date >> last10.txt","check":{"type":"lines","path":"/home/student/last10.txt","count":11},"explain":"Timestamps like this are a cheap way to log when a script ran."},{"text":"Run `ls nofile`, saving only the error message in `err.log`. Then run it again, appending the error.","hints":["Errors are file descriptor 2: 2> and 2>>."],"solution":"ls nofile 2> err.log\nls nofile 2>> err.log","check":{"type":"lines","path":"/home/student/err.log","count":2},"explain":"Collecting errors in a file is the classic way to log problems from a script that runs unattended."},{"text":"Run `ls ~ nofile` and save both its output and its error in `all.log`.","hints":["&> sends both streams."],"solution":"ls ~ nofile &> all.log","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/all.log","text":"No such file"},{"type":"contains","path":"/home/student/all.log","text":"server.log"}]},"explain":"`&>` is bash shorthand for `> all.log 2>&1`."}],"from":["text"],"obj":"3.2","lesson":"3.2.1","lessonTitle":"Redirection and pipes","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_01/","part":1,"parts":3},{"id":"3.2.1-b","title":"Feeding input","intro":"`<` feeds a file to a command's standard input. A here document (`<<WORD`) feeds the lines you type until a line with just WORD.","setup":{"files":[{"path":"~/server.log","data":"10:00 ERROR disk\n10:01 ok\n10:02 ok\n10:03 ok\n10:04 ok\n10:05 ok\n10:06 ok\n10:07 ERROR disk\n10:08 ok\n10:09 ok\n10:10 ok\n10:11 ok\n10:12 ok\n10:13 ok\n10:14 ERROR disk\n10:15 ok\n10:16 ok\n10:17 ok\n10:18 ok\n10:19 ok\n10:20 ok\n10:21 ERROR disk\n10:22 ok\n10:23 ok\n10:24 ok\n10:25 ok\n10:26 ok\n10:27 ok\n10:28 ERROR disk\n10:29 ok\n"},{"path":"~/phone.txt","data":"555-123-4567\n"}]},"commands":["wc","cat","tr"],"tasks":[{"text":"Count the words in `server.log` by feeding it on standard input.","hints":["wc -w, with < instead of a file argument."],"solution":"wc -w < server.log","check":{"type":"all","checks":[{"type":"last","regex":"^\\d+\\n$"},{"type":"history","regex":"wc\\s+-w\\s*<"}]},"explain":"With `<`, wc doesn't know the file name, so it prints only the number."},{"text":"Create `list.txt` holding three lines, `apples`, `pears`, `plums`, using cat and a here document.","hints":["cat > list.txt <<EOF, then the lines, then EOF on its own line.","The terminal shows > while it waits for the end marker."],"solution":"cat > list.txt <<EOF\napples\npears\nplums\nEOF","check":{"type":"equals","path":"/home/student/list.txt","text":"apples\npears\nplums\n"},"explain":"Here documents are common in scripts for writing config files or multi-line messages."},{"text":"Print `phone.txt` with all dashes removed. tr reads only standard input.","hints":["tr -d - deletes dashes; give it the file with <."],"solution":"tr -d - < phone.txt","check":{"type":"last","regex":"^5551234567\\n$"},"explain":"tr is one of the few common tools that won't take a file name.","mistakes":[{"cmd":"^\\s*tr\\s+-d\\s+-\\s+phone\\.txt","out":"extra operand","say":"tr doesn't accept file names. Feed the file with `<`: `tr -d - < phone.txt`.","try":"tr -d - phone.txt"}]}],"obj":"3.2","lesson":"3.2.1","lessonTitle":"Redirection and pipes","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_01/","part":2,"parts":3},{"id":"3.2.1-c","title":"Pipes","intro":"A pipe `|` connects one command's output to the next one's input, so small tools can be chained.","setup":{"files":[{"path":"~/names.txt","data":"Zoe\nadam\nMaria\nbob\nChen\ndara\nEli\nfarah\nGus\nhana\nIvan\njune\n"},{"path":"~/pics/cat.jpg","data":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"},{"path":"~/pics/dog.png","data":""},{"path":"/usr/share/games/test","data":""},{"path":"/usr/share/doc/tar/test","data":""},{"path":"/usr/share/lab/a/b/test","data":""},{"path":"/usr/share/lab/testing","data":""}]},"commands":["head","sort","tail","wc","find","ls","tr","cut"],"tasks":[{"text":"Show the first 5 lines of `names.txt`, sorted in reverse.","hints":["head -n 5, then pipe into sort -r."],"solution":"head -n 5 names.txt | sort -r","check":{"type":"last","regex":"^bob\\nadam\\nZoe\\nMaria\\nChen\\n$"},"explain":"Uppercase letters sort before lowercase in the C locale, so `Zoe` comes after `adam` when reversed."},{"text":"Count the characters in the last 3 lines of `names.txt`.","hints":["tail -n 3, piped into wc with its byte-count option."],"solution":"tail -n 3 names.txt | wc -c","check":{"type":"last","regex":"^15\\n$"},"explain":"Newlines count as characters too."},{"text":"Count how many files named `test` exist under `/usr/share`.","hints":["find ... -name test, piped into wc -l."],"solution":"find /usr/share -name test | wc -l","check":{"type":"last","regex":"^3\\n$"},"explain":"Counting lines of output is a very common pipe ending."},{"text":"Print only the file names from `ls -l pics`: squeeze repeated spaces, then cut the 9th space-separated field.","hints":["tr -s ' ' squeezes spaces.","cut -d' ' -f9"],"solution":"ls -l pics | tr -s ' ' | cut -d' ' -f9","check":{"type":"all","checks":[{"type":"last","regex":"cat\\.jpg"},{"type":"last","regex":"dog\\.png"},{"type":"not","check":{"type":"last","regex":"student"}}]},"explain":"Without the squeeze, cut would count every single space as a field separator."},{"text":"Sort `names.txt` case-insensitively, in reverse.","hints":["sort -f ignores case; combine with -r."],"solution":"sort -fr names.txt","check":{"type":"last","regex":"^Zoe\\nMaria\\njune\\nIvan\\n"},"explain":"`-f` folds case only for the comparison; the output keeps the original case."}],"obj":"3.2","lesson":"3.2.1","lessonTitle":"Redirection and pipes","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_01/","part":3,"parts":3},{"id":"3.2.2-a","title":"Basic regular expressions","intro":"`words.txt` has one word per line. In a regular expression `.` is any character, `^` and `$` anchor the start and end of the line, `[abc]` is one of a set, and `*` repeats the previous item.","setup":{"files":[{"path":"~/words.txt","data":"cat\ncatalog\nconcatenate\nscatter\ndog\ndug\napple\nmaple\npeople\nstaple\ntree\nfree\nagree\ncoffee\nflu\nkayak\nokay\ntuna\nfortune\norgan\norganize\nread\nready\nreader\nradio\nrad\nbread\n4th\n10th\nnth\nspot\npot\napot\npotion\nspots\nHawaii\nDario\nRamiro\nhawaii\nIgor\nAlice\nlynx\nsky\nrhythm\nmyth\n"}]},"commands":["grep"],"tasks":[{"text":"Show every line that contains `cat` anywhere.","hints":["grep PATTERN FILE"],"solution":"grep cat words.txt","check":{"type":"all","checks":[{"type":"last","regex":"concatenate"},{"type":"last","regex":"scatter"},{"type":"not","check":{"type":"last","regex":"dog"}}]},"explain":"A plain word matches anywhere in the line."},{"text":"Count the lines that contain none of the letters a, e, i, o.","hints":["Invert the match (-v) and count (-c). The set is [aeio]."],"solution":"grep -vc '[aeio]' words.txt","check":{"type":"last","regex":"^9\\n$"},"explain":"`-v` keeps the lines that DON'T match, `-c` prints a count instead of lines."},{"text":"Show the lines that start with exactly two characters followed by `ple`.","hints":["^ anchors the start; each . is one character."],"solution":"grep '^..ple' words.txt","check":{"type":"all","checks":[{"type":"last","regex":"^apple\\nmaple\\n$"}]},"explain":"`people` doesn't match: its 3rd to 5th letters are `opl`, not `ple`. Quote patterns so the shell leaves them alone."},{"text":"Show the lines that end with `e`.","hints":["$ anchors the end."],"solution":"grep 'e$' words.txt","check":{"type":"all","checks":[{"type":"last","regex":"tree"},{"type":"last","regex":"coffee"},{"type":"not","check":{"type":"last","regex":"organize\\n.*organ\\n"}}]},"explain":"`e$` means an e right before the end of the line."},{"text":"Find `hawaii` in any capitalization.","hints":["grep's ignore-case option."],"solution":"grep -i hawaii words.txt","check":{"type":"last","regex":"^Hawaii\\nhawaii\\n$"},"explain":"`-i` is the quickest fix when you don't know how something was capitalized."}],"obj":"3.2","lesson":"3.2.2","lessonTitle":"Searching text: grep, regular expressions and sed","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_02/","part":1,"parts":3},{"id":"3.2.2-b","title":"Extended regular expressions","intro":"With `grep -E`, `+` (one or more), `?` (optional), `|` (or) and `()` work without backslashes.","setup":{"files":[{"path":"~/words.txt","data":"cat\ncatalog\nconcatenate\nscatter\ndog\ndug\napple\nmaple\npeople\nstaple\ntree\nfree\nagree\ncoffee\nflu\nkayak\nokay\ntuna\nfortune\norgan\norganize\nread\nready\nreader\nradio\nrad\nbread\n4th\n10th\nnth\nspot\npot\napot\npotion\nspots\nHawaii\nDario\nRamiro\nhawaii\nIgor\nAlice\nlynx\nsky\nrhythm\nmyth\n"}]},"commands":["grep"],"tasks":[{"text":"Show the lines containing `org`, `kay` or `tuna`.","hints":["-E and the | operator."],"solution":"grep -E 'org|kay|tuna' words.txt","check":{"type":"all","checks":[{"type":"last","regex":"organ"},{"type":"last","regex":"kayak"},{"type":"last","regex":"okay"},{"type":"last","regex":"tuna"},{"type":"not","check":{"type":"last","regex":"fortune"}}]},"explain":"A line matches if any one alternative appears in it: organ, organize, kayak, okay and tuna. `fortune` contains `tun` but not `tuna`.","mistakes":[{"cmd":"^\\s*grep\\s+'org\\|kay\\|tuna'","say":"In basic regular expressions `|` is an ordinary character, so grep looked for the literal text `org|kay|tuna`. Add `-E`.","try":"grep 'org|kay|tuna' words.txt"}]},{"text":"Count the lines that start with `r`, an optional `e`, then `ad`.","hints":["? makes the previous character optional. Anchor with ^, count with -c."],"solution":"grep -Ec '^re?ad' words.txt","check":{"type":"last","regex":"^5\\n$"},"explain":"`read`, `ready`, `reader`, `rad` and `radio` all match; `bread` doesn't start with r."},{"text":"Show the lines with a digit followed by `th`.","hints":["[0-9] is any digit."],"solution":"grep '[0-9]th' words.txt","check":{"type":"last","regex":"^4th\\n10th\\n$"},"explain":"`nth` has no digit, so it's left out."},{"text":"Show the lines that END in `pot`.","hints":["Anchor the end with $."],"solution":"grep 'pot$' words.txt","check":{"type":"last","regex":"^spot\\npot\\napot\\n$"},"explain":"`potion` and `spots` contain pot but don't end with it."},{"text":"Show the lines that start with a capital letter followed by `a`.","hints":["[A-Z] is one capital letter."],"solution":"grep '^[A-Z]a' words.txt","check":{"type":"last","regex":"^Hawaii\\nDario\\nRamiro\\n$"},"explain":"`Igor` and `Alice` start with a capital but the next letter isn't a."}],"obj":"3.2","lesson":"3.2.2","lessonTitle":"Searching text: grep, regular expressions and sed","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_02/","part":2,"parts":3},{"id":"3.2.2-c","title":"sed, recursive grep and filters","intro":"`sed 's/old/new/g'` replaces text in every line it reads. `grep -r` searches whole directory trees.","setup":{"files":[{"path":"~/styles.txt","data":"h1 { colour: red; }\np { colour: blue; background-colour: white; }\n"},{"path":"~/project/main.c","data":"int main() { /* TODO: args */ }\n"},{"path":"~/project/lib/util.c","data":"// TODO speed up\n"},{"path":"~/project/README","data":"nothing to do\n"},{"path":"~/project/shared","dir":true,"mode":509},{"path":"~/project/private","dir":true,"mode":448}]},"commands":["sed","grep","ls","tr"],"tasks":[{"text":"Print `styles.txt` with every `colour` changed to `color` (don't change the file yet).","hints":["sed 's/colour/color/g' FILE"],"solution":"sed 's/colour/color/g' styles.txt","check":{"type":"all","checks":[{"type":"last","regex":"color: red"},{"type":"not","check":{"type":"last","regex":"colour"}}]},"explain":"Without the `g`, only the first match on each line would change."},{"text":"Now make that change in the file itself.","hints":["sed has an in-place option."],"solution":"sed -i 's/colour/color/g' styles.txt","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/styles.txt","text":"color: red"},{"type":"not","check":{"type":"contains","path":"/home/student/styles.txt","text":"colour"}}]},"explain":"Test without `-i` first, as you just did; `sed -i.bak` keeps a backup copy."},{"text":"Search every file under `~/project` for `TODO`.","hints":["grep's recursive option."],"solution":"grep -r TODO ~/project","check":{"type":"all","checks":[{"type":"last","regex":"main\\.c:"},{"type":"last","regex":"util\\.c:"}]},"explain":"Recursive grep prefixes each line with the file name."},{"text":"Count the accounts in `/etc/passwd` whose shell does NOT end in `nologin`.","hints":["-v and -c, with a pattern anchored at the end."],"solution":"grep -vc 'nologin$' /etc/passwd","check":{"type":"last","regex":"^2\\n$"},"explain":"Those are the accounts that can log in interactively: root and student."},{"text":"From `ls -l ~/project`, show only the entries whose GROUP permissions are rwx.","hints":["The group bits are characters 5 to 7 of the mode.","ls -l ~/project | tr -s ' ' | grep '^....rwx'"],"solution":"ls -l ~/project | tr -s ' ' | grep '^....rwx'","check":{"type":"all","checks":[{"type":"last","regex":"shared"},{"type":"not","check":{"type":"last","regex":"private"}}]},"explain":"Each `.` skips one character: the type plus the three owner bits. `tr -s ' '` isn't needed for this pattern, but squeezing spaces first makes columns easy to cut later."}],"obj":"3.2","lesson":"3.2.2","lessonTitle":"Searching text: grep, regular expressions and sed","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.2/3.2_02/","part":3,"parts":3},{"id":"3.3.1-a","title":"Your first script","intro":"A script is a text file of commands. The first line, the **shebang** (`#!`), names the interpreter. Type `nano FILE` to open an editor panel, or write files with a here document.","setup":{},"commands":["which","cat","chmod"],"tasks":[{"text":"Find the full path of bash, for the shebang line.","hints":["which bash"],"solution":"which bash","check":{"type":"last","regex":"^/usr/bin/bash\\n$"},"explain":"`#!/bin/bash` works too, because /bin is a link to /usr/bin on current systems."},{"text":"Create `hello.sh` with a bash shebang and a line that prints `Hello, Linux`.","hints":["Line 1: #!/bin/bash   Line 2: echo \"Hello, Linux\"","cat > hello.sh <<'EOF' ... EOF, or nano hello.sh"],"solution":"cat > hello.sh <<'EOF'\n#!/bin/bash\necho \"Hello, Linux\"\nEOF","check":{"type":"all","checks":[{"type":"contains","path":"/home/student/hello.sh","regex":"^#!/(usr/)?bin/(ba)?sh","flags":"m"},{"type":"contains","path":"/home/student/hello.sh","text":"Hello, Linux"}]},"explain":"Quoting the heredoc marker ('EOF') stops the shell from expanding `$` signs inside it, which matters in scripts."},{"text":"Try running it as `./hello.sh`. Then make it executable and run it again.","hints":["A new file isn't executable.","chmod +x hello.sh"],"solution":"./hello.sh\nchmod +x hello.sh\n./hello.sh","check":{"type":"all","checks":[{"type":"last","regex":"^Hello, Linux\\n$"},{"type":"perms","path":"/home/student/hello.sh","perms":"-rwxr-xr-x"}]},"explain":"`./` is needed because the current directory isn't in PATH. `bash hello.sh` would run it even without the execute bit."},{"text":"Show the script with line numbers.","hints":["cat -n"],"solution":"cat -n hello.sh","check":{"type":"last","regex":"^\\s+1\\t#!"},"explain":"Error messages from bash include line numbers, so this helps when debugging."}],"from":["scripts"],"obj":"3.3","lesson":"3.3.1","lessonTitle":"Shell scripts: shebang, PATH, arguments and tests","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_01/","part":1,"parts":3},{"id":"3.3.1-b","title":"Running scripts by name: PATH","intro":"Your `~/scripts` directory holds an executable script `greet`. The shell only finds commands by name in the directories listed in PATH. The default PATH is `/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin`.","setup":{"files":[{"path":"~/scripts/greet","data":"#!/bin/bash\necho \"Hello from greet\"\n","mode":493}]},"commands":["env","grep"],"tasks":[{"text":"Try to run `greet` by name.","hints":["Just type greet."],"solution":"greet","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*greet\\s*$"},{"type":"last","regex":"greet: command not found"}]},"explain":"`~/scripts` isn't in PATH, so the shell can't find it."},{"text":"Set PATH to just `~/scripts` and try `ls`.","hints":["PATH=~/scripts"],"solution":"PATH=~/scripts\nls","check":{"type":"all","checks":[{"type":"var","name":"PATH","value":"/home/student/scripts"},{"type":"last","regex":"ls: command not found"}]},"explain":"Everything outside `~/scripts` is gone, so even ls can't be found. This mistake is common in scripts and crontabs."},{"text":"Fix PATH: the full default from the intro, with `~/scripts` added at the end.","hints":["PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:~/scripts"],"solution":"PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:~/scripts","check":{"type":"var","name":"PATH","value":"/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/home/student/scripts"},"explain":"Appending keeps system commands first, so your script can't accidentally replace one. In a working shell you'd write `PATH=$PATH:~/scripts`."},{"text":"Run `greet` by name.","hints":["greet"],"solution":"greet","check":{"type":"last","regex":"^Hello from greet\\n$"},"explain":"Put the PATH line in `~/.bashrc` to make it permanent."},{"text":"Use `env` and `grep` to find the environment variable holding your current directory.","hints":["env | grep, with a pattern anchored at the start of the line."],"solution":"env | grep '^PWD'","check":{"type":"last","regex":"^PWD=/home/student\\n$"},"explain":"`$PWD` is updated by cd; `$OLDPWD` holds the previous directory."}],"obj":"3.3","lesson":"3.3.1","lessonTitle":"Shell scripts: shebang, PATH, arguments and tests","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_01/","part":2,"parts":3},{"id":"3.3.1-c","title":"Arguments and tests","intro":"Inside a script, `$1`, `$2`... are the arguments and `$#` is how many there are. `[ ... ]` (the test command) compares values: `-eq -ne -gt -ge -lt -le` for numbers, `=` and `!=` for text.","setup":{},"commands":["chmod"],"tasks":[{"text":"Create an executable `swap.sh` that prints its two arguments in reverse order, so `./swap.sh red blue` prints `blue red`.","hints":["echo \"$2 $1\"","Don't forget the shebang and chmod +x."],"solution":"cat > swap.sh <<'EOF'\n#!/bin/bash\necho \"$2 $1\"\nEOF\nchmod +x swap.sh","check":{"type":"script","path":"./swap.sh","args":"red blue","output":"blue red\n"},"explain":"Arguments are split on spaces unless quoted: `./swap.sh 'dark red' blue` keeps `dark red` together."},{"text":"Make `swap.sh` print `Need exactly 2 arguments` and exit with status 1 unless it gets exactly two.","hints":["if [ $# -ne 2 ]; then ... exit 1; fi","Put the check before the echo."],"solution":"cat > swap.sh <<'EOF'\n#!/bin/bash\nif [ $# -ne 2 ]; then\n  echo \"Need exactly 2 arguments\"\n  exit 1\nfi\necho \"$2 $1\"\nEOF","check":{"type":"all","checks":[{"type":"script","path":"./swap.sh","args":"a","output":"Need exactly 2 arguments\n","code":1},{"type":"script","path":"./swap.sh","args":"a b","output":"b a\n"}]},"explain":"Checking arguments first and exiting with a non-zero status is what makes a script safe to use from other scripts."},{"text":"Create an executable `compare.sh` that prints `bigger`, `smaller` or `equal` comparing `$1` with `$2` as numbers.","hints":["if [ \"$1\" -gt \"$2\" ]; then ... elif [ \"$1\" -lt \"$2\" ]; then ... else ... fi"],"solution":"cat > compare.sh <<'EOF'\n#!/bin/bash\nif [ \"$1\" -gt \"$2\" ]; then\n  echo bigger\nelif [ \"$1\" -lt \"$2\" ]; then\n  echo smaller\nelse\n  echo equal\nfi\nEOF\nchmod +x compare.sh","check":{"type":"all","checks":[{"type":"script","path":"./compare.sh","args":"3 1","output":"bigger\n"},{"type":"script","path":"./compare.sh","args":"2 4","output":"smaller\n"},{"type":"script","path":"./compare.sh","args":"5 5","output":"equal\n"}]},"explain":"The spaces inside `[ ... ]` are required: `[` is a command and its arguments must be separate words."},{"text":"Show the difference between number and text comparison: run `[ 010 -eq 10 ] && echo numeric` and `[ 010 = 10 ] || echo text` on one line.","hints":["Separate the two with ;"],"solution":"[ 010 -eq 10 ] && echo numeric; [ 010 = 10 ] || echo text","check":{"type":"last","regex":"^numeric\\ntext\\n$"},"explain":"As numbers, 010 equals 10; as text, the strings differ. `==` works like `=` in bash."}],"from":["scripts"],"obj":"3.3","lesson":"3.3.1","lessonTitle":"Shell scripts: shebang, PATH, arguments and tests","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_01/","part":3,"parts":3},{"id":"3.3.2-a","title":"Exit status","intro":"Every command ends with an exit status: 0 means success, anything else is an error code. `$?` holds the last one, and `&&` / `||` act on it.","setup":{},"commands":["ls","echo","grep","chmod"],"tasks":[{"text":"Run `ls` on a directory that doesn't exist, then print its exit status.","hints":["echo $? right after it."],"solution":"ls /nope\necho $?","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ls\\s+/nope"},{"type":"last","regex":"(^|\\n)2\\n$"}]},"explain":"ls uses 2 for 'serious trouble', such as a missing argument."},{"text":"Print the exit status of a grep that finds nothing.","hints":["grep zzz /etc/hosts; echo $?"],"solution":"grep zzz /etc/hosts; echo $?","check":{"type":"last","regex":"^1\\n$"},"explain":"grep returns 0 when it finds something, 1 when it doesn't and 2 on errors, which makes it perfect for `if`."},{"text":"Create an executable `upper.sh` that exits with 0 if `$1` contains only capital letters, and 1 otherwise. It shouldn't print anything.","hints":["echo \"$1\" | grep -q '^[A-Z]*$' tests it quietly.","The script's exit status is the status of its last command."],"solution":"cat > upper.sh <<'EOF'\n#!/bin/bash\necho \"$1\" | grep -q '^[A-Z][A-Z]*$'\nEOF\nchmod +x upper.sh","check":{"type":"all","checks":[{"type":"script","path":"./upper.sh","args":"CAKE","output":"","code":0},{"type":"script","path":"./upper.sh","args":"cake","output":"","code":1}]},"explain":"`grep -q` prints nothing; only its exit status matters. Try `./upper.sh CAKE && echo yes`."}],"obj":"3.3","lesson":"3.3.2","lessonTitle":"Shell scripts: exit status, loops and shift","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_02/","part":1,"parts":3},{"id":"3.3.2-b","title":"Loops","intro":"`for x in LIST; do ...; done` repeats for each item; `while CONDITION; do ...; done` repeats while the condition succeeds. In the terminal you can type a loop over several lines (the prompt shows `>`).","setup":{"files":[{"path":"~/docs/a.txt","data":"a\n"},{"path":"~/docs/b.txt","data":"b\n"},{"path":"~/docs/c.md","data":"c\n"}]},"commands":["echo","cat","cp","chmod"],"tasks":[{"text":"Use a for loop to print `number 1`, `number 2` and `number 3`.","hints":["for n in 1 2 3; do echo \"number $n\"; done"],"solution":"for n in 1 2 3; do echo \"number $n\"; done","check":{"type":"last","regex":"^number 1\\nnumber 2\\nnumber 3\\n$"},"explain":"`for n in {1..3}` or `$(seq 3)` would work too."},{"text":"Count down from 3 with a while loop, printing `3 2 1 liftoff` on one line.","hints":["n=3; while [ $n -gt 0 ]; do echo -n \"$n \"; n=$((n-1)); done; echo liftoff","echo -n leaves out the newline."],"solution":"n=3; while [ $n -gt 0 ]; do echo -n \"$n \"; n=$((n-1)); done; echo liftoff","check":{"type":"last","regex":"^3 2 1 liftoff\\n$"},"explain":"`$(( ))` does integer arithmetic."},{"text":"Create an executable `backup.sh` that copies every `.txt` file in the directory given as `$1` to the same name plus `.bak`. Run it on `docs`.","hints":["for f in \"$1\"/*.txt; do cp \"$f\" \"$f.bak\"; done"],"solution":"cat > backup.sh <<'EOF'\n#!/bin/bash\nfor f in \"$1\"/*.txt; do\n  cp \"$f\" \"$f.bak\"\ndone\nEOF\nchmod +x backup.sh\n./backup.sh docs","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/docs/a.txt.bak"},{"type":"exists","path":"/home/student/docs/b.txt.bak"},{"type":"absent","path":"/home/student/docs/c.md.bak"}]},"explain":"Quoting `\"$f\"` keeps file names with spaces in one piece."},{"text":"Create an executable `big.sh` that prints only those arguments that are whole numbers greater than 10, so `./big.sh 5 12 x 30` prints `12` and `30`.","hints":["Loop over \"$@\". Test that it's a number first (grep -qE '^[0-9]+$'), then -gt 10.","if echo \"$n\" | grep -qE '^[0-9]+$' && [ \"$n\" -gt 10 ]; then echo \"$n\"; fi"],"solution":"cat > big.sh <<'EOF'\n#!/bin/bash\nfor n in \"$@\"; do\n  if echo \"$n\" | grep -qE '^[0-9]+$' && [ \"$n\" -gt 10 ]; then\n    echo \"$n\"\n  fi\ndone\nEOF\nchmod +x big.sh","check":{"type":"script","path":"./big.sh","args":"5 12 x 30","output":"12\n30\n"},"explain":"Without the number check, `[ x -gt 10 ]` prints 'integer expression expected'. `&&` only runs the test when grep succeeded."}],"obj":"3.3","lesson":"3.3.2","lessonTitle":"Shell scripts: exit status, loops and shift","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_02/","part":2,"parts":3},{"id":"3.3.2-c","title":"shift","intro":"`shift` throws away `$1` and moves the other arguments down: `$2` becomes `$1`, and `$#` drops by one. It's how scripts walk through any number of arguments.","setup":{},"commands":["cat","chmod"],"tasks":[{"text":"Create an executable `first.sh` that prints `$1`, runs `shift`, then prints `$1` and `$#` again. `./first.sh a b c` should print `a` then `b 2`.","hints":["echo $1\nshift\necho $1 $#"],"solution":"cat > first.sh <<'EOF'\n#!/bin/bash\necho $1\nshift\necho $1 $#\nEOF\nchmod +x first.sh","check":{"type":"script","path":"./first.sh","args":"a b c","output":"a\nb 2\n"},"explain":"After shift, `$1` is the old `$2`."},{"text":"Create an executable `each.sh` that prints `arg: X` for every argument, using a while loop and shift.","hints":["while [ $# -gt 0 ]; do echo \"arg: $1\"; shift; done"],"solution":"cat > each.sh <<'EOF'\n#!/bin/bash\nwhile [ $# -gt 0 ]; do\n  echo \"arg: $1\"\n  shift\ndone\nEOF\nchmod +x each.sh","check":{"type":"script","path":"./each.sh","args":"one two three","output":"arg: one\narg: two\narg: three\n"},"explain":"This pattern is the basis of option parsing in many scripts: look at `$1`, handle it, shift."},{"text":"Show `each.sh` with line numbers.","hints":["cat -n each.sh"],"solution":"cat -n each.sh","check":{"type":"last","regex":"\\s+3\\t\\s*echo"},"explain":"Now you can read error messages like `each.sh: line 3: ...`."}],"obj":"3.3","lesson":"3.3.2","lessonTitle":"Shell scripts: exit status, loops and shift","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_02/","part":3,"parts":3},{"id":"4.1.1-a","title":"Kernel and distribution","intro":"Linux is the kernel; the distribution (Ubuntu, Fedora, Debian...) is the kernel plus everything around it. Two commands tell you which is which.","setup":{},"commands":["uname","cat"],"tasks":[{"text":"Print the kernel's name.","hints":["uname with the 'system name' option."],"solution":"uname -s","check":{"type":"last","regex":"^Linux\\n$"},"explain":"Plain `uname` prints the same thing."},{"text":"Print the kernel release.","hints":["uname -r"],"solution":"uname -r","check":{"type":"last","regex":"^6\\.8\\.0-45-generic\\n$"},"explain":"Major.minor.patch, then the distribution's build number. It matches the `vmlinuz-...` file in /boot."},{"text":"Print everything uname knows.","hints":["uname -a"],"solution":"uname -a","check":{"type":"last","regex":"x86_64"},"explain":"Includes the host name and the hardware architecture (x86_64 here; aarch64 on a Raspberry Pi)."},{"text":"Find out which distribution and version this is.","hints":["The distribution describes itself in /etc/os-release."],"solution":"cat /etc/os-release","check":{"type":"last","regex":"VERSION_ID"},"explain":"`ID_LIKE=debian` tells scripts which family's tools (apt, dpkg) to expect."}],"obj":"4.1","lesson":"4.1.1","lessonTitle":"Which system is this?","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.1/4.1_01/","part":1,"parts":1},{"id":"4.2.1-a","title":"Looking at the hardware","intro":"Linux shows hardware through commands and through files in `/dev` and `/proc`. Storage: SATA/USB disks are `sda`, `sdb`...; SD cards and eMMC are `mmcblk0`; NVMe drives are `nvme0n1`.","setup":{},"commands":["lscpu","free","lsblk","ls"],"tasks":[{"text":"Show information about the processor.","hints":["ls + cpu"],"solution":"lscpu","check":{"type":"last","regex":"Model name"},"explain":"Look for the architecture, number of cores and the `vmx` or `svm` flag, which means hardware virtualization is supported."},{"text":"Show memory use in megabytes.","hints":["free with the MiB option."],"solution":"free -m","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*free\\s+-m"},{"type":"last","regex":"Mem:"}]},"explain":"`available` is the useful number: free memory plus cache the kernel can give back."},{"text":"List the block devices (disks and partitions).","hints":["lsblk"],"solution":"lsblk","check":{"type":"last","regex":"mmcblk0p2"},"explain":"There's a hard disk (sda, two partitions), a DVD drive (sr0) and an SD card (mmcblk0)."},{"text":"Show the file systems on each partition.","hints":["lsblk has an option for file system details."],"solution":"lsblk -f","check":{"type":"last","regex":"FSTYPE"},"explain":"vfat is the EFI/boot partition format, ext4 the usual Linux file system. UUIDs are how /etc/fstab often refers to partitions."},{"text":"List the SD card's device files in `/dev` in long format.","hints":["ls -l /dev/mmcblk*"],"solution":"ls -l /dev/mmcblk*","check":{"type":"last","regex":"(^|\\n)brw-rw----.*mmcblk0p1"},"explain":"The `b` means a block device. Members of the `disk` group can access the raw disk, which is why that group is effectively root-level."}],"obj":"4.2","lesson":"4.2.1","lessonTitle":"Hardware: CPU, memory and storage devices","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.2/4.2_01/","part":1,"parts":1},{"id":"4.3.1-a","title":"Programs and configuration","intro":"Programs for everyone live in `/usr/bin`, administration programs in `/usr/sbin`. System-wide settings are in `/etc`; your personal ones are hidden files in `~`.","setup":{},"commands":["which","useradd","ls"],"tasks":[{"text":"Find where `passwd` and `useradd` are installed, with one command.","hints":["which accepts several names."],"solution":"which passwd useradd","check":{"type":"last","regex":"^/usr/bin/passwd\\n/usr/sbin/useradd\\n$"},"explain":"The `sbin` directories hold commands meant for administrators."},{"text":"Try `useradd test` as yourself.","hints":["Just run it."],"solution":"useradd test","check":{"type":"last","regex":"Permission denied"},"explain":"You can run the program, but it can't change /etc/passwd without root. That's what `sudo` is for."},{"text":"List the hidden default configuration files that every new user gets.","hints":["They're copied from /etc/skel; hidden files need -a."],"solution":"ls -a /etc/skel","check":{"type":"last","regex":"\\.bashrc"},"explain":"`useradd -m` copies /etc/skel into the new home. Edit it to change defaults for future users."},{"text":"Show what `/bin` really is.","hints":["List the entry itself in long format."],"solution":"ls -ld /bin","check":{"type":"last","regex":"/bin -> usr/bin"},"explain":"On current distributions /bin, /sbin and /lib are links into /usr."}],"obj":"4.3","lesson":"4.3.1","lessonTitle":"Where data is stored: programs, configuration, kernel and memory","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_01/","part":1,"parts":2},{"id":"4.3.1-b","title":"Kernel and memory","intro":"The kernel and initial RAM disk live in `/boot`. The kernel exposes live information as files in `/proc`.","setup":{},"commands":["ls","uname","free","grep"],"tasks":[{"text":"List the files in `/boot`.","hints":["ls /boot"],"solution":"ls /boot","check":{"type":"last","regex":"vmlinuz-6\\.8\\.0-45-generic"},"explain":"`vmlinuz-VERSION` is the compressed kernel, `initrd.img-VERSION` the initial RAM disk it starts with."},{"text":"Check that the running kernel's release matches a file in /boot.","hints":["uname -r"],"solution":"uname -r","check":{"type":"last","regex":"^6\\.8\\.0-45-generic\\n$"},"explain":"Several kernels can be installed; the boot loader picks one."},{"text":"Show memory use in human-readable units.","hints":["free -h"],"solution":"free -h","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*free\\s+-\\w*h"},{"type":"last","regex":"Gi"}]},"explain":"`-b`, `-m` and `-g` choose bytes, MiB or GiB; `-h` picks for you."},{"text":"Show the `MemTotal` line of the file free reads its numbers from.","hints":["It's /proc/meminfo. grep the line."],"solution":"grep MemTotal /proc/meminfo","check":{"type":"last","regex":"^MemTotal:\\s+8048424 kB\\n$"},"explain":"`free` just formats /proc/meminfo. /proc files are generated by the kernel when you read them."}],"from":["system"],"obj":"4.3","lesson":"4.3.1","lessonTitle":"Where data is stored: programs, configuration, kernel and memory","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_01/","part":2,"parts":2},{"id":"4.3.2-a","title":"Processes","intro":"Every running program is a process with a number (PID). Something on this system is eating a whole CPU core.","setup":{"procs":[{"pid":3141,"user":"student","cmd":"yes","cpu":99.7,"stat":"R","tty":"pts/1","time":"12:41"}]},"commands":["ps","top","kill"],"tasks":[{"text":"List your processes on this terminal.","hints":["ps with no options."],"solution":"ps","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ps\\s*$"},{"type":"last","regex":"bash"}]},"explain":"Plain ps only shows this terminal's processes: your shell and ps itself."},{"text":"Show them again in full format, with parent PIDs.","hints":["ps -f"],"solution":"ps -f","check":{"type":"last","regex":"PPID"},"explain":"PPID is the parent: ps was started by your bash, which was started by sshd."},{"text":"List every process on the system, BSD style.","hints":["ps aux"],"solution":"ps aux","check":{"type":"last","regex":"/sbin/init"},"explain":"PID 1 is init (systemd), the ancestor of every other process."},{"text":"Show the same list as a tree.","hints":["Add f to aux."],"solution":"ps auxf","check":{"type":"last","regex":"\\\\_ "},"explain":"The tree shows who started what: sshd → sshd → bash → ps."},{"text":"Find the process using the most CPU with top.","hints":["top sorts by CPU."],"solution":"top","check":{"type":"last","regex":"3141 student.*yes"},"explain":"In real top, press `k` to kill a PID, `M` to sort by memory, `q` to quit."},{"text":"Stop it. It's yours, so you don't need sudo.","hints":["kill PID (from ps or top)."],"solution":"kill 3141","check":{"type":"noproc","cmd":"yes"},"explain":"kill sends SIGTERM (15), asking the program to exit cleanly. Use `kill -9` only if that doesn't work."},{"text":"Try to kill the nginx worker (PID 780), which belongs to www-data.","hints":["kill 780"],"solution":"kill 780","check":{"type":"last","regex":"Operation not permitted"},"explain":"Users can only signal their own processes; root can signal any."}],"obj":"4.3","lesson":"4.3.2","lessonTitle":"Where data is stored: processes, /proc and logs","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_02/","part":1,"parts":3},{"id":"4.3.2-b","title":"/proc and $$","intro":"The kernel shows each process as a directory in `/proc`, named after its PID. `$$` is your shell's own PID.","setup":{},"commands":["echo","ls","cat","bash","exit","exec"],"tasks":[{"text":"Print your shell's PID.","hints":["The special variable $$."],"solution":"echo $$","check":{"type":"last","regex":"^2301\\n$"},"explain":"ps showed the same number for bash."},{"text":"List the directory /proc keeps for PID 1.","hints":["ls /proc/1"],"solution":"ls /proc/1","check":{"type":"last","regex":"cmdline"},"explain":"Each process directory has its command line, status, environment and more."},{"text":"Show PID 1's command line.","hints":["cat /proc/1/cmdline"],"solution":"cat /proc/1/cmdline","check":{"type":"last","regex":"/sbin/init"},"explain":"Arguments are separated by invisible NUL bytes, so they run together on screen."},{"text":"Start a child shell, print its PID, then leave it.","hints":["bash, then echo $$, then exit."],"solution":"bash\necho $$\nexit","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*bash\\s*$"},{"type":"history","regex":"^\\s*echo\\s+\\$\\$"},{"type":"shell","depth":0},{"type":"last","regex":"^exit\\n$"}]},"explain":"The child had a new PID; back in the parent, `$$` is 2301 again."},{"text":"Replace your shell with a new bash using exec, then print the PID.","hints":["exec bash, then echo $$."],"solution":"exec bash\necho $$","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*exec\\s+bash"},{"type":"last","regex":"^2301\\n$"}]},"explain":"exec replaces the current program instead of starting a child, so the PID stays the same. Unexported variables are gone."}],"obj":"4.3","lesson":"4.3.2","lessonTitle":"Where data is stored: processes, /proc and logs","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_02/","part":2,"parts":3},{"id":"4.3.2-c","title":"Logs","intro":"Logs record what happened: login records in binary files read by `last`, kernel messages via `dmesg`, and the systemd journal via `journalctl`. You're in the `adm` group, which may read most logs.","setup":{},"commands":["last","lastb","file","dmesg","grep","journalctl","tail"],"tasks":[{"text":"Find out when the system last booted.","hints":["last can show reboot records."],"solution":"last reboot","check":{"type":"last","regex":"system boot"},"explain":"last reads /var/log/wtmp."},{"text":"Show failed login attempts.","hints":["lastb needs root."],"solution":"sudo lastb","check":{"type":"last","regex":"203\\.0\\.113\\.7"},"explain":"Repeated failures for root from the internet are typical SSH password-guessing. Disable root SSH logins!"},{"text":"Find out what kind of file `/var/log/wtmp` is.","hints":["file PATH"],"solution":"file /var/log/wtmp","check":{"type":"last","regex":"data"},"explain":"It's binary, which is why you read it with last instead of cat."},{"text":"Search the kernel ring buffer for the USB disk `sdb`.","hints":["dmesg needs root; pipe into grep."],"solution":"sudo dmesg | grep sdb","check":{"type":"last","regex":"sdb: sdb1"},"explain":"When you plug in a USB stick, dmesg tells you which device name it got."},{"text":"Show the same kernel messages from the journal.","hints":["journalctl option for kernel messages."],"solution":"journalctl -k","check":{"type":"last","regex":"kernel:"},"explain":"`journalctl -k` is the journal's version of dmesg."},{"text":"Show the SSH server's log messages.","hints":["journalctl -u UNIT"],"solution":"journalctl -u ssh","check":{"type":"last","regex":"Failed password"},"explain":"`-u` filters by systemd unit; try cron or nginx too. `-f` follows new messages."},{"text":"Show the messages from the PREVIOUS boot.","hints":["-b takes an offset; -1 is the boot before this one."],"solution":"journalctl -b -1","check":{"type":"last","regex":"powering down"},"explain":"Great for finding out why a machine rebooted or crashed."},{"text":"Show the last 2 lines of `/var/log/auth.log`.","hints":["tail -n 2"],"solution":"tail -n 2 /var/log/auth.log","check":{"type":"last","regex":"COMMAND=/usr/bin/apt update"},"explain":"Every sudo use is logged. `tail -f` would keep printing new lines as they arrive."}],"obj":"4.3","lesson":"4.3.2","lessonTitle":"Where data is stored: processes, /proc and logs","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_02/","part":3,"parts":3},{"id":"4.4.1-a","title":"Interfaces and addresses","intro":"`ip` (iproute2) shows and changes network settings. Changes need root and last until reboot. The wired interface here is `enp0s3`.","setup":{},"commands":["ip"],"tasks":[{"text":"List the network interfaces.","hints":["ip link show"],"solution":"ip link show","check":{"type":"last","regex":"enp0s3"},"explain":"`lo` is the loopback interface (127.0.0.1); `enp0s3` is the first Ethernet card with a predictable name."},{"text":"Show their IP addresses.","hints":["ip addr show (or just ip a)"],"solution":"ip addr show","check":{"type":"last","regex":"192\\.168\\.1\\.42/24"},"explain":"/24 means the first 24 bits are the network: 192.168.1.x."},{"text":"Add the address `192.168.10.10/24` to `enp0s3`.","hints":["sudo ip addr add ADDRESS/PREFIX dev DEVICE"],"solution":"sudo ip addr add 192.168.10.10/24 dev enp0s3","check":{"type":"addr","dev":"enp0s3","addr":"192.168.10.10/24"},"explain":"An interface can have several addresses. 192.168.x.x, 10.x.x.x and 172.16-31.x.x are private ranges.","mistakes":[{"cmd":"^\\s*ip\\s+a\\w*\\s+add","out":"Operation not permitted","say":"Changing network settings needs root: put `sudo` in front.","try":"ip addr add 192.168.10.10/24 dev enp0s3"}]},{"text":"Add the IPv6 address `2001:db8:0:abcd::10/64` to `enp0s3`.","hints":["Same command; ip recognises IPv6."],"solution":"sudo ip addr add 2001:db8:0:abcd::10/64 dev enp0s3","check":{"type":"addr","dev":"enp0s3","addr":"2001:db8:0:abcd::10/64"},"explain":"`::` stands for a run of zero groups. 2001:db8::/32 is reserved for documentation."},{"text":"Show every interface on one line each, with its addresses.","hints":["ip has a brief option, -br."],"solution":"ip -br addr","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ip\\s+-br"},{"type":"last","regex":"192\\.168\\.10\\.10/24"}]},"explain":"Brief output is easy to read and to parse in scripts."}],"obj":"4.4","lesson":"4.4.1","lessonTitle":"Your computer on the network","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":1,"parts":4},{"id":"4.4.1-b","title":"Routes and reachability","intro":"Someone deleted this machine's default route. Without one, it can only reach its own local network.","setup":{"run":["sudo ip route del default"]},"commands":["ip","ping","ping6"],"tasks":[{"text":"Show the routing table.","hints":["ip route show"],"solution":"ip route show","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ip\\s+r\\w*(\\s+show)?\\s*$"},{"type":"not","check":{"type":"last","regex":"default"}}]},"explain":"Only the local network 192.168.1.0/24 is listed; there's no 'default via' line."},{"text":"Try to ping `example.com` 3 times.","hints":["ping -c 3 HOST"],"solution":"ping -c 3 example.com","check":{"type":"last","regex":"Network is unreachable"},"explain":"Without a gateway the kernel doesn't know where to send packets for other networks."},{"text":"Add the default route via the gateway `192.168.1.1`.","hints":["sudo ip route add default via GATEWAY"],"solution":"sudo ip route add default via 192.168.1.1","check":{"type":"route","dst":"default","via":"192.168.1.1"},"explain":"The default gateway is usually your router."},{"text":"Ping `example.com` 3 times again.","hints":["ping -c 3 example.com"],"solution":"ping -c 3 example.com","check":{"type":"last","regex":"3 packets transmitted, 3 received"},"explain":"On Linux ping keeps going until Ctrl+C unless you give `-c`."},{"text":"Add an IPv6 default route via `2001:db8:0:abcd::1`.","hints":["ip -6 route add default via ..."],"solution":"sudo ip -6 route add default via 2001:db8:0:abcd::1","check":{"type":"route","v6":true,"dst":"default","via":"2001:db8:0:abcd::1"},"explain":"IPv4 and IPv6 have separate routing tables."},{"text":"Ping the IPv6 loopback address `::1` once.","hints":["ping6 (or ping -6)."],"solution":"ping6 -c 1 ::1","check":{"type":"last","regex":"1 packets transmitted"},"explain":"`::1` is IPv6's 127.0.0.1."}],"obj":"4.4","lesson":"4.4.1","lessonTitle":"Your computer on the network","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":2,"parts":4},{"id":"4.4.1-c","title":"Name resolution","intro":"Names are turned into addresses by `/etc/hosts` first, then by the DNS servers listed in `/etc/resolv.conf`.","setup":{},"commands":["cat","host","dig","tee","ping"],"tasks":[{"text":"Show which DNS servers this system uses.","hints":["cat /etc/resolv.conf"],"solution":"cat /etc/resolv.conf","check":{"type":"last","regex":"nameserver"},"explain":"On systemd systems this often points to 127.0.0.53, a local cache."},{"text":"Look up `example.com` with host.","hints":["host NAME"],"solution":"host example.com","check":{"type":"last","regex":"has address"},"explain":"host gives a short answer: addresses and mail servers."},{"text":"Look it up with dig and find which server answered.","hints":["dig NAME; look at the SERVER line."],"solution":"dig example.com","check":{"type":"last","regex":";; SERVER:"},"explain":"dig shows the whole answer, including TTL and timing; it's the troubleshooting tool."},{"text":"Ask for `lpi.org`'s mail server, printing only the answer.","hints":["Record type MX; +short trims the output."],"solution":"dig +short MX lpi.org","check":{"type":"last","regex":"mail\\.lpi\\.org"},"explain":"MX records say where mail for a domain should go."},{"text":"Make the name `fileserver` resolve to `192.168.0.15` on this machine.","hints":["Add a line to /etc/hosts. It's root-owned.","echo '192.168.0.15 fileserver' | sudo tee -a /etc/hosts"],"solution":"echo '192.168.0.15 fileserver' | sudo tee -a /etc/hosts","check":{"type":"contains","path":"/etc/hosts","regex":"192\\.168\\.0\\.15\\s+fileserver"},"explain":"`sudo tee -a` does the writing as root. With `sudo echo ... >>`, the redirection is done by your own shell, as you.","mistakes":[{"cmd":"sudo\\s+echo.*>>\\s*/etc/hosts","out":"Permission denied","say":"The `>>` is handled by YOUR shell before sudo starts, so it runs as you. Pipe into `sudo tee -a /etc/hosts` instead.","try":"sudo echo '192.168.0.15 fileserver' >> /etc/hosts"}]},{"text":"Ping `fileserver` once.","hints":["ping -c 1 fileserver"],"solution":"ping -c 1 fileserver","check":{"type":"last","regex":"192\\.168\\.0\\.15"},"explain":"/etc/hosts is checked before DNS, so this works with no DNS server at all."}],"from":["network"],"obj":"4.4","lesson":"4.4.1","lessonTitle":"Your computer on the network","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":3,"parts":4},{"id":"4.4.1-d","title":"Sockets and ports","intro":"`ss` lists network connections. By default it shows established connections; options filter by protocol and state.","setup":{},"commands":["ss"],"tasks":[{"text":"Show established TCP connections.","hints":["ss -t"],"solution":"ss -t","check":{"type":"last","regex":"ESTAB"},"explain":"Your SSH session is one of them: 192.168.1.42:22 ↔ 192.168.1.20."},{"text":"Show listening TCP sockets.","hints":["Add -l."],"solution":"ss -tl","check":{"type":"last","regex":"LISTEN"},"explain":"Port 22 is SSH, 80 is HTTP."},{"text":"Show established UDP sockets.","hints":["-u for UDP."],"solution":"ss -u","check":{"type":"last","regex":"1\\.1\\.1\\.1:53"},"explain":"UDP is connectionless; 'established' here means the socket is connected to one peer, like this DNS query."},{"text":"Show a summary of all sockets.","hints":["ss -s"],"solution":"ss -s","check":{"type":"last","regex":"^Total:"},"explain":"A quick overview when a server seems overloaded."},{"text":"Show every listening TCP and UDP port with the program behind it, as numbers.","hints":["-t -u -l -p -n; -p needs root to see other users' programs."],"solution":"sudo ss -tulpn","check":{"type":"last","regex":"sshd"},"explain":"`sudo ss -tulpn` is the standard answer to 'what is listening on this machine?'"},{"text":"Show only IPv6 listening sockets.","hints":["-6 with -l."],"solution":"ss -l6","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ss\\s+-\\w*6|-6"},{"type":"last","regex":"\\[::\\]"}]},"explain":"`-4` would show only IPv4."}],"obj":"4.4","lesson":"4.4.1","lessonTitle":"Your computer on the network","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":4,"parts":4},{"id":"5.1.1-a","title":"Who am I?","intro":"Every user has a numeric user ID (UID) and belongs to groups. Accounts are listed in `/etc/passwd`; password hashes are in `/etc/shadow`, which only root can read.","setup":{},"commands":["id","whoami","groups","grep","cat","sudo"],"tasks":[{"text":"Show your UID, primary group and all groups.","hints":["A two-letter command."],"solution":"id","check":{"type":"last","regex":"uid=1000\\(student\\)"},"explain":"UID 0 is root. Regular users start at 1000 on most distributions."},{"text":"Print just your user name.","hints":["whoami"],"solution":"whoami","check":{"type":"last","regex":"^student\\n$"},"explain":"Useful in scripts, and after sudo or su when you're not sure who you are."},{"text":"List your group names.","hints":["groups"],"solution":"groups","check":{"type":"last","regex":"sudo"},"explain":"Being in `sudo` (Debian/Ubuntu) or `wheel` (Fedora/RHEL) is what lets you use sudo."},{"text":"Show your own line from `/etc/passwd`.","hints":["grep your name in the file."],"solution":"grep student /etc/passwd","check":{"type":"last","regex":"^student:x:1000:1000:"},"explain":"Fields: name, x (hash is in shadow), UID, GID, comment, home, shell."},{"text":"Try to read `/etc/shadow`.","hints":["cat /etc/shadow"],"solution":"cat /etc/shadow","check":{"type":"last","regex":"Permission denied"},"explain":"Keeping hashes unreadable stops users from trying to crack each other's passwords offline."},{"text":"Read your shadow entry with root rights.","hints":["sudo grep student /etc/shadow"],"solution":"sudo grep student /etc/shadow","check":{"type":"last","regex":"^student:\\$y\\$"},"explain":"`$y$` marks a yescrypt hash. The numbers after it are password-aging fields."}],"obj":"5.1","lesson":"5.1.1","lessonTitle":"Users: who am I, who's logged in, and switching users","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.1/5.1_01/","part":1,"parts":3},{"id":"5.1.1-b","title":"Who else is here?","intro":"`who` and `w` show current logins; `last` shows past ones.","setup":{},"commands":["who","w","last"],"tasks":[{"text":"Show who is logged in.","hints":["who"],"solution":"who","check":{"type":"last","regex":"pts/0"},"explain":"`tty2` is a local console login; `pts/0` is a remote (SSH) or terminal-window session."},{"text":"Show who is logged in and what they're doing, with uptime and load.","hints":["w"],"solution":"w","check":{"type":"last","regex":"load average"},"explain":"The first line is the same as `uptime`."},{"text":"Run w with no header, IP addresses instead of names, and the short format.","hints":["Options -h, -i and -s, which can be combined."],"solution":"w -his","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*w\\s+-[his]{3}\\s*$|^\\s*w(\\s+-[his])+\\s*$"},{"type":"last","regex":"192\\.168\\.1\\.20"},{"type":"not","check":{"type":"last","regex":"load average"}}]},"explain":"Handy for scripts that only want the list."},{"text":"List recent logins, including ones that ended.","hints":["last"],"solution":"last","check":{"type":"last","regex":"wtmp begins"},"explain":"last reads /var/log/wtmp: who, from where, and how long."},{"text":"List only your own past logins.","hints":["last NAME"],"solution":"last student","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*last\\s+student"},{"type":"not","check":{"type":"last","regex":"reboot"}}]},"explain":"Give last a user name, tty or `reboot` to filter."}],"obj":"5.1","lesson":"5.1.1","lessonTitle":"Users: who am I, who's logged in, and switching users","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.1/5.1_01/","part":2,"parts":3},{"id":"5.1.1-c","title":"Switching users and changing your details","intro":"`su` switches user with the TARGET's password; `sudo` runs commands as root with YOUR password, if you're allowed. On Ubuntu root has no password at all.","setup":{},"commands":["su","sudo","exit","chsh","chfn","grep"],"tasks":[{"text":"Try to become root with `su -`.","hints":["su -"],"solution":"su -","check":{"type":"last","regex":"Authentication failure"},"explain":"Root's password is locked on Ubuntu, so su to root fails. That's deliberate: admins use sudo, which logs who did what."},{"text":"Start a root login shell with sudo instead.","hints":["sudo -i"],"solution":"sudo -i","check":{"type":"whoami","name":"root"},"explain":"The prompt ends in `#` now. Be careful: everything you do is as root."},{"text":"Leave the root shell.","hints":["exit"],"solution":"exit","check":{"type":"all","checks":[{"type":"whoami","name":"student"},{"type":"history","regex":"^\\s*exit\\s*$"}]},"explain":"Use root shells briefly; `sudo COMMAND` for single commands is safer."},{"text":"Change your own login shell to `/bin/sh`.","hints":["chsh with -s; you'll be asked for your password."],"solution":"chsh -s /bin/sh","check":{"type":"user","name":"student","shell":"/bin/sh"},"explain":"Only shells listed in /etc/shells are allowed. The change applies at your next login."},{"text":"Set your full name to `Ada Student` and your work phone to `555-0100`.","hints":["chfn -f NAME -w PHONE"],"solution":"chfn -f 'Ada Student' -w 555-0100","check":{"type":"user","name":"student","comment":"Ada Student,,555-0100,"},"explain":"These go into the comment (GECOS) field of /etc/passwd, separated by commas."},{"text":"Find out which users may use sudo here.","hints":["They are the members of the sudo group, listed in /etc/group."],"solution":"grep sudo /etc/group","check":{"type":"last","regex":"^sudo:x:27:student\\n$"},"explain":"To give someone sudo: `sudo usermod -aG sudo NAME`."}],"obj":"5.1","lesson":"5.1.1","lessonTitle":"Users: who am I, who's logged in, and switching users","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.1/5.1_01/","part":3,"parts":3},{"id":"5.2.1-a","title":"The account files","intro":"Four files hold accounts and groups: `/etc/passwd`, `/etc/shadow`, `/etc/group` and `/etc/gshadow`.","setup":{},"commands":["tail","ls"],"tasks":[{"text":"Show the last three accounts in `/etc/passwd`.","hints":["tail -3 or tail -n 3"],"solution":"tail -3 /etc/passwd","check":{"type":"last","regex":"student:x:1000"},"explain":"System accounts like www-data have shells like /usr/sbin/nologin so nobody can log in as them."},{"text":"Show the last three lines of `/etc/group`.","hints":["Same, for /etc/group."],"solution":"tail -n 3 /etc/group","check":{"type":"last","regex":"student:x:1000:"},"explain":"Every user gets a private group with the same name (user private groups)."},{"text":"Compare the permissions of the four account files.","hints":["ls -l with all four paths."],"solution":"ls -l /etc/passwd /etc/shadow /etc/group /etc/gshadow","check":{"type":"all","checks":[{"type":"last","regex":"-rw-r----- .*/etc/shadow"},{"type":"last","regex":"-rw-r--r-- .*/etc/passwd"}]},"explain":"passwd and group are world-readable because programs need names and IDs; the shadow files hold secrets."},{"text":"Look at the permissions of the `passwd` program.","hints":["ls -l /usr/bin/passwd"],"solution":"ls -l /usr/bin/passwd","check":{"type":"last","regex":"^-rwsr-xr-x"},"explain":"The `s` is the SUID bit: passwd runs as its owner, root, so it can write /etc/shadow for you."}],"obj":"5.2","lesson":"5.2.1","lessonTitle":"Creating and managing users and groups","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.2/5.2_01/","part":1,"parts":4},{"id":"5.2.1-b","title":"Groups","intro":"Groups let you give several users the same access. Creating them needs root.","setup":{},"commands":["sudo","groupadd","grep"],"tasks":[{"text":"Create the groups `sys_admin`, `web_admin` and `db_admin`.","hints":["sudo groupadd NAME, once per group (or a for loop)."],"solution":"sudo groupadd sys_admin\nsudo groupadd web_admin\nsudo groupadd db_admin","check":{"type":"all","checks":[{"type":"group","name":"sys_admin"},{"type":"group","name":"web_admin"},{"type":"group","name":"db_admin"}]},"explain":"Without -g, groupadd picks the next free GID above 1000.","mistakes":[{"cmd":"^\\s*groupadd\\s","out":"Permission denied","say":"Creating groups needs root: `sudo groupadd ...`.","try":"groupadd sys_admin"}]},{"text":"Create the group `developers` with GID 2000.","hints":["groupadd's option for the GID."],"solution":"sudo groupadd -g 2000 developers","check":{"type":"group","name":"developers","gid":2000},"explain":"Fixed GIDs keep file ownership consistent across servers sharing files over NFS."},{"text":"Show the three admin groups in `/etc/group`.","hints":["grep admin /etc/group"],"solution":"grep admin /etc/group","check":{"type":"last","regex":"db_admin:x:\\d+:"},"explain":"The last field (members) is empty until users are added."}],"obj":"5.2","lesson":"5.2.1","lessonTitle":"Creating and managing users and groups","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.2/5.2_01/","part":2,"parts":4},{"id":"5.2.1-c","title":"Users","intro":"The groups `sys_admin`, `web_admin`, `db_admin` and `developers` exist. Now create some accounts.","setup":{"groups":[{"name":"sys_admin","gid":1100},{"name":"web_admin","gid":1101},{"name":"db_admin","gid":1102},{"name":"developers","gid":2000}]},"commands":["sudo","useradd","passwd","id","usermod"],"tasks":[{"text":"Create user `dave` with a home directory.","hints":["useradd with the option that makes a home."],"solution":"sudo useradd -m dave","check":{"type":"user","name":"dave","homeExists":true},"explain":"`-m` copies /etc/skel into /home/dave. Debian's useradd doesn't create homes by default.","mistakes":[{"cmd":"useradd\\s+dave\\s*$","say":"That created dave without a home directory. Remove him (`sudo userdel dave`) and add `-m`.","try":"sudo useradd dave"}]},{"text":"Can dave log in? Check his password status.","hints":["passwd -S NAME (needs root)."],"solution":"sudo passwd -S dave","check":{"type":"last","regex":"^dave L "},"explain":"`L` means locked: useradd doesn't set a password, so nobody can log in as dave yet."},{"text":"Give dave a password.","hints":["sudo passwd NAME"],"solution":"sudo passwd dave","check":{"type":"user","name":"dave","password":"set"},"explain":"Now `passwd -S dave` shows `P` (usable password)."},{"text":"Create `carol` with UID 1035, primary group `sys_admin`, extra groups `web_admin` and `db_admin`, Bash as shell, comment `Carol Smith`, and a home directory.","hints":["-u UID, -g primary, -G list, -s shell, -c comment, -m"],"solution":"sudo useradd -m -u 1035 -g sys_admin -G web_admin,db_admin -s /bin/bash -c 'Carol Smith' carol","check":{"type":"user","name":"carol","uid":1035,"primary":"sys_admin","groups":["web_admin","db_admin"],"shell":"/bin/bash","comment":"Carol Smith","homeExists":true},"explain":"With -g, no private carol group is created."},{"text":"Check carol's IDs and groups.","hints":["id NAME"],"solution":"id carol","check":{"type":"last","regex":"^uid=1035\\(carol\\) gid=1100\\(sys_admin\\)"},"explain":"id works on any user, not just yourself."},{"text":"Create a service account `temp`: no home directory, shell `/usr/sbin/nologin`, account expiring on 2026-12-31, disabled 5 days after its password expires.","hints":["-M no home, -s shell, -e YYYY-MM-DD, -f days."],"solution":"sudo useradd -M -s /usr/sbin/nologin -e 2026-12-31 -f 5 temp","check":{"type":"all","checks":[{"type":"user","name":"temp","shell":"/usr/sbin/nologin"},{"type":"absent","path":"/home/temp"},{"type":"contains","path":"/etc/shadow","regex":"^temp:[^:]*:\\d+:0:99999:7:5:20818:","flags":"m"}]},"explain":"In /etc/shadow, 5 is the inactive field and 20818 (days since 1970) is the expiry date."},{"text":"Add dave to `developers` without removing him from his other groups.","hints":["usermod -aG GROUP NAME"],"solution":"sudo usermod -aG developers dave","check":{"type":"user","name":"dave","groups":["developers"]},"explain":"Without -a, -G replaces the whole list of extra groups."}],"from":["users"],"obj":"5.2","lesson":"5.2.1","lessonTitle":"Creating and managing users and groups","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.2/5.2_01/","part":3,"parts":4},{"id":"5.2.1-d","title":"Passwords and cleaning up","intro":"Users `dave` (with a password) and `temp` exist, and so do the admin groups.","setup":{"groups":[{"name":"sys_admin","gid":1100},{"name":"web_admin","gid":1101},{"name":"db_admin","gid":1102},{"name":"developers","gid":2000}],"users":[{"name":"dave","groups":["developers"]},{"name":"temp","home":false,"shell":"/usr/sbin/nologin"}]},"commands":["sudo","passwd","userdel","groupdel"],"tasks":[{"text":"Lock dave's password.","hints":["passwd -l"],"solution":"sudo passwd -l dave","check":{"type":"user","name":"dave","password":"locked-set"},"explain":"Locking puts `!` in front of the hash; the old password still exists for when you unlock."},{"text":"Unlock it again.","hints":["passwd -u"],"solution":"sudo passwd -u dave","check":{"type":"all","checks":[{"type":"user","name":"dave","password":"set"},{"type":"history","regex":"passwd\\s+-u\\s+dave"}]},"explain":"Lock instead of delete when someone is on leave."},{"text":"Force dave to choose a new password at his next login.","hints":["passwd -e expires the password."],"solution":"sudo passwd -e dave","check":{"type":"contains","path":"/etc/shadow","regex":"^dave:[^:]*:0:","flags":"m"},"explain":"A last-change date of 0 in /etc/shadow forces the change. Do this after setting a temporary password."},{"text":"Remove `temp`'s password entirely.","hints":["passwd -d"],"solution":"sudo passwd -d temp","check":{"type":"user","name":"temp","password":"empty"},"explain":"An empty password is dangerous for real users; here temp can't log in anyway because of its nologin shell."},{"text":"Delete dave and his home directory.","hints":["userdel with -r."],"solution":"sudo userdel -r dave","check":{"type":"all","checks":[{"type":"nouser","name":"dave"},{"type":"absent","path":"/home/dave"}]},"explain":"Without -r the home directory stays, owned by a UID that no longer has a name."},{"text":"Delete the group `db_admin`.","hints":["groupdel NAME"],"solution":"sudo groupdel db_admin","check":{"type":"nogroup","name":"db_admin"},"explain":"groupdel refuses to delete a group that is someone's primary group."}],"obj":"5.2","lesson":"5.2.1","lessonTitle":"Creating and managing users and groups","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.2/5.2_01/","part":4,"parts":4},{"id":"5.3.1-a","title":"Reading permissions","intro":"In `ls -l`, the first character is the type (`-` file, `d` directory, `l` link, `b`/`c` device) and the next nine are read/write/execute for the owner, the group and others.","setup":{},"commands":["mkdir","ls","groups"],"tasks":[{"text":"Create a directory `emptydir` and show ITS permissions (not its contents).","hints":["mkdir, then ls -ld."],"solution":"mkdir emptydir\nls -ld emptydir","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/emptydir","kind":"dir"},{"type":"last","regex":"^drwxr-xr-x .* emptydir\\n$"}]},"explain":"`-d` makes ls describe the directory itself."},{"text":"Look at the device file `/dev/sda1`.","hints":["ls -l /dev/sda1"],"solution":"ls -l /dev/sda1","check":{"type":"last","regex":"^brw-rw---- 1 root disk"},"explain":"`b` = block device. Root and the disk group can read and write the raw partition."},{"text":"List the groups you belong to.","hints":["groups"],"solution":"groups","check":{"type":"last","regex":"student"},"explain":"Group permissions apply if the file's group is one of these."}],"obj":"5.3","lesson":"5.3.1","lessonTitle":"Permissions and ownership","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":1,"parts":5},{"id":"5.3.1-b","title":"Symbolic mode","intro":"Symbolic chmod: who (`u` owner, `g` group, `o` others, `a` all), then `+`, `-` or `=`, then the bits (`r w x`). Several changes can be joined with commas.","setup":{"files":[{"path":"~/emptyfile","data":"","mode":438},{"path":"~/report.txt","data":"q3\n"},{"path":"~/private.txt","data":"","mode":384},{"path":"~/tool.sh","data":"#!/bin/bash\n","mode":429},{"path":"~/project/notes.txt","data":"n\n"},{"path":"~/project/src","dir":true,"mode":429}]},"commands":["chmod"],"tasks":[{"text":"Give the owner of `emptyfile` execute permission and remove write and execute from group and others, in one command.","hints":["Two clauses separated by a comma: u+x,go-wx"],"solution":"chmod u+x,go-wx emptyfile","check":{"type":"perms","path":"/home/student/emptyfile","perms":"-rwxr--r--"},"explain":"Symbolic mode changes only the bits you mention."},{"text":"Let the group write to `report.txt`.","hints":["g+w"],"solution":"chmod g+w report.txt","check":{"type":"perms","path":"/home/student/report.txt","perms":"-rw-rw-r--"},"explain":"Other bits stay as they were."},{"text":"Set `private.txt` so everyone can read and write it, and nobody can execute it.","hints":["a=rw sets exactly those bits for all three."],"solution":"chmod a=rw private.txt","check":{"type":"perms","path":"/home/student/private.txt","perms":"-rw-rw-rw-"},"explain":"`=` replaces the bits instead of adding or removing."},{"text":"Give the owner full rights on `tool.sh` and remove execute from the group.","hints":["u+rwx,g-x"],"solution":"chmod u+rwx,g-x tool.sh","check":{"type":"perms","path":"/home/student/tool.sh","perms":"-rwxr--r-x"},"explain":"Others keep their x: you only changed u and g."},{"text":"Give the owner full rights on `project` and everything inside it.","hints":["chmod has a recursive option, capital R."],"solution":"chmod -R u+rwx project","check":{"type":"all","checks":[{"type":"perms","path":"/home/student/project/notes.txt","perms":"-rwxr--r--"},{"type":"perms","path":"/home/student/project/src","perms":"drwxr-xr-x"}]},"explain":"Careful with -R and x: files you didn't want to be executable become so. `X` (capital) adds x only to directories."}],"from":["perms"],"obj":"5.3","lesson":"5.3.1","lessonTitle":"Permissions and ownership","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":2,"parts":5},{"id":"5.3.1-c","title":"Octal mode","intro":"Octal chmod gives each of owner, group and others a digit: read 4 + write 2 + execute 1. So 7 is rwx, 6 rw-, 5 r-x, 4 r--, 0 ---.","setup":{"files":[{"path":"~/text.txt","data":"t\n"},{"path":"~/shared.txt","data":"s\n"},{"path":"~/locked.txt","data":"secret\n"}]},"commands":["chmod","cat","ls"],"tasks":[{"text":"Set `text.txt` to `rwxr-xr--`.","hints":["7 5 4"],"solution":"chmod 754 text.txt","check":{"type":"perms","path":"/home/student/text.txt","perms":"-rwxr-xr--"},"explain":"rwx = 4+2+1 = 7, r-x = 4+1 = 5, r-- = 4."},{"text":"Make `shared.txt` readable and writable by owner and group only.","hints":["rw- rw- ---"],"solution":"chmod 660 shared.txt","check":{"type":"mode","path":"/home/student/shared.txt","mode":"660"},"explain":"660 is common for files a team edits together."},{"text":"Take away every permission from `locked.txt`, then try to read it.","hints":["chmod 000, then cat."],"solution":"chmod 000 locked.txt\ncat locked.txt","check":{"type":"all","checks":[{"type":"mode","path":"/home/student/locked.txt","mode":"0"},{"type":"last","regex":"Permission denied"}]},"explain":"Even the owner can't read it now, but the owner can still chmod it back. Root ignores read/write bits."},{"text":"Run `chmod 4 locked.txt` and look at the result with ls -l. Which set got the 4?","hints":["Missing leading digits count as 0."],"solution":"chmod 4 locked.txt\nls -l locked.txt","check":{"type":"perms","path":"/home/student/locked.txt","perms":"-------r--"},"explain":"Digits are read from the right: a single digit sets 'others' only. `chmod 44` would set group and others."}],"from":["perms"],"obj":"5.3","lesson":"5.3.1","lessonTitle":"Permissions and ownership","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":3,"parts":5},{"id":"5.3.1-d","title":"Ownership","intro":"Every file has an owner and a group. You're in the group `team`, and the user `carol` exists.","setup":{"groups":[{"name":"team","gid":3000,"members":["student"]}],"users":[{"name":"carol"}],"files":[{"path":"~/report.txt","data":"q3\n"}]},"commands":["chgrp","sudo","chown","groupmems"],"tasks":[{"text":"Change the group of `report.txt` to `team`.","hints":["chgrp GROUP FILE"],"solution":"chgrp team report.txt","check":{"type":"owner","path":"/home/student/report.txt","group":"team"},"explain":"You may change a file's group to any group you belong to, without sudo."},{"text":"Make `carol` the owner and `team` the group of `report.txt` in one command.","hints":["chown USER:GROUP FILE. Giving files away needs root."],"solution":"sudo chown carol:team report.txt","check":{"type":"owner","path":"/home/student/report.txt","user":"carol","group":"team"},"explain":"Only root can give a file to someone else; otherwise users could dodge disk quotas.","mistakes":[{"cmd":"^\\s*chown\\s","out":"Operation not permitted","say":"Only root can change a file's owner: `sudo chown carol:team report.txt`.","try":"chown carol:team report.txt"}]},{"text":"Change only the group of `report.txt` to `users`, using chown.","hints":["chown :GROUP FILE"],"solution":"sudo chown :users report.txt","check":{"type":"owner","path":"/home/student/report.txt","user":"carol","group":"users"},"explain":"A leading colon means 'group only'."},{"text":"List the members of the group `team`.","hints":["groupmems -g GROUP -l (needs root)."],"solution":"sudo groupmems -g team -l","check":{"type":"last","regex":"student"},"explain":"`getent group team` or `grep team /etc/group` show the same."}],"obj":"5.3","lesson":"5.3.1","lessonTitle":"Permissions and ownership","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":4,"parts":5},{"id":"5.3.1-e","title":"Special permissions: SUID, SGID and sticky","intro":"A fourth leading octal digit sets special bits: 4 SUID (run as the file's owner), 2 SGID (run as the group; on a directory, new files inherit its group), 1 sticky (in a shared directory, only owners can delete their files).","setup":{"files":[{"path":"~/pubdir","dir":true},{"path":"~/suidtool","data":"ELF","mode":2541},{"path":"~/sgidscript","data":"#!/bin/bash\n","mode":1517}]},"commands":["mkdir","sudo","chgrp","chmod","touch","ls"],"tasks":[{"text":"Create a shared directory `Box` owned by group `users`.","hints":["mkdir Box, then change its group (you're not in users, so use sudo)."],"solution":"mkdir Box\nsudo chgrp users Box","check":{"type":"owner","path":"/home/student/Box","group":"users"},"explain":"Next, make it a proper shared folder."},{"text":"Set `Box` to full access for owner and group, nothing for others, plus SGID and sticky.","hints":["SGID 2 + sticky 1 = 3, then 770."],"solution":"chmod 3770 Box","check":{"type":"mode","path":"/home/student/Box","mode":"3770"},"explain":"`ls -ld Box` shows `drwxrws--T`: s for SGID, capital T because others have no x."},{"text":"Create `Box/report` and check its group.","hints":["touch it, then ls -l Box."],"solution":"touch Box/report\nls -l Box","check":{"type":"owner","path":"/home/student/Box/report","group":"users"},"explain":"Thanks to SGID the file joined the directory's group instead of your own."},{"text":"Make `pubdir` world-readable with the sticky bit: `rwxr-xr-t`.","hints":["1 for sticky, then 755."],"solution":"chmod 1755 pubdir","check":{"type":"perms","path":"/home/student/pubdir","perms":"drwxr-xr-t"},"explain":"`/tmp` is 1777: everyone may create files, but only owners may delete them."},{"text":"`suidtool` has SUID set. Remove the owner's execute bit and look at it.","hints":["chmod u-x, then ls -l."],"solution":"chmod u-x suidtool\nls -l suidtool","check":{"type":"perms","path":"/home/student/suidtool","perms":"-rwSr-xr-x"},"explain":"A capital S means SUID is set but execute isn't, which is almost always a mistake."},{"text":"Clear the special bit on `sgidscript` (currently 2755) with a four-digit octal mode, keeping rwxr-xr-x.","hints":["A leading 0 clears the special bits."],"solution":"chmod 0755 sgidscript","check":{"type":"mode","path":"/home/student/sgidscript","mode":"755"},"explain":"Being explicit with four digits makes your intent clear."}],"obj":"5.3","lesson":"5.3.1","lessonTitle":"Permissions and ownership","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":5,"parts":5},{"id":"5.4.1-a","title":"Temporary directories and the sticky bit","intro":"`/tmp` is for short-lived files (often cleared at boot), `/var/tmp` for temporary files that must survive a reboot, and `/run` for runtime data, always cleared at boot.","setup":{"users":[{"name":"carol"}],"files":[{"path":"/tmp/carol.txt","data":"mine\n","owner":"carol"}]},"commands":["ls","touch","mkdir","chmod","rm"],"tasks":[{"text":"Compare the permissions of `/tmp`, `/var/tmp` and `/run`.","hints":["ls -ld with all three."],"solution":"ls -ld /tmp /var/tmp /run","check":{"type":"all","checks":[{"type":"last","regex":"drwxrwxrwt .* /tmp"},{"type":"last","regex":"/run"}]},"explain":"The `t` in /tmp and /var/tmp is the sticky bit."},{"text":"Create `keep.txt` in the temporary directory that survives reboots.","hints":["Not /tmp."],"solution":"touch /var/tmp/keep.txt","check":{"type":"exists","path":"/var/tmp/keep.txt"},"explain":"Programs that need temporary data across a reboot, like package managers, use /var/tmp."},{"text":"Create `~/dropbox`, make it writable by everyone, then add the sticky bit with symbolic mode.","hints":["mkdir, chmod 777, then chmod +t."],"solution":"mkdir ~/dropbox\nchmod 777 ~/dropbox\nchmod +t ~/dropbox","check":{"type":"mode","path":"/home/student/dropbox","mode":"1777"},"explain":"`+t` is the symbolic form of the leading 1."},{"text":"Try to delete carol's file `/tmp/carol.txt`.","hints":["rm /tmp/carol.txt"],"solution":"rm /tmp/carol.txt","check":{"type":"all","checks":[{"type":"exists","path":"/tmp/carol.txt"},{"type":"last","regex":"Operation not permitted"}]},"explain":"/tmp is world-writable, but the sticky bit stops you deleting other people's files."}],"from":["special"],"obj":"5.4","lesson":"5.4.1","lessonTitle":"Temporary directories and links","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.4/5.4_01/","part":1,"parts":3},{"id":"5.4.1-b","title":"Hard links","intro":"A hard link is a second name for the same file (the same inode). Neither name is the 'original'.","setup":{"files":[{"path":"~/recipes.txt","data":"pancakes: flour, milk, eggs\n"}]},"commands":["ln","ls","rm","cat"],"tasks":[{"text":"Create a hard link `rezepte.txt` to `recipes.txt`.","hints":["ln TARGET NEWNAME"],"solution":"ln recipes.txt rezepte.txt","check":{"type":"hardlink","path":"/home/student/rezepte.txt","other":"/home/student/recipes.txt"},"explain":"No -s means hard link."},{"text":"Show both names with their inode numbers.","hints":["ls -li"],"solution":"ls -li recipes.txt rezepte.txt","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ls\\s+-\\w*i"},{"type":"last","regex":"^(\\d+) .* 2 .*recipes\\.txt\\n\\1 "}]},"explain":"Same inode number, and the link count is 2."},{"text":"Delete `recipes.txt`, then print `rezepte.txt`.","hints":["rm, then cat."],"solution":"rm recipes.txt\ncat rezepte.txt","check":{"type":"all","checks":[{"type":"absent","path":"/home/student/recipes.txt"},{"type":"last","regex":"pancakes"}]},"explain":"The data stays until the last name is removed."}],"from":["special"],"obj":"5.4","lesson":"5.4.1","lessonTitle":"Temporary directories and links","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.4/5.4_01/","part":2,"parts":3},{"id":"5.4.1-c","title":"Symbolic links","intro":"A symbolic (soft) link is a small file holding a path. It can point to directories and other file systems, but it breaks if the target goes away.","setup":{"files":[{"path":"~/Documents/document.txt","data":"doc\n"},{"path":"~/notes.txt","data":"first\n"}]},"commands":["ln","ls","rm","cat","echo"],"tasks":[{"text":"Create a symbolic link `text.txt` pointing to `/home/student/Documents/document.txt`.","hints":["ln -s TARGET LINKNAME"],"solution":"ln -s /home/student/Documents/document.txt text.txt","check":{"type":"link","path":"/home/student/text.txt","target":"/home/student/Documents/document.txt"},"explain":"An absolute target keeps working if you move the link."},{"text":"Look at the link with ls -l.","hints":["ls -l text.txt"],"solution":"ls -l text.txt","check":{"type":"last","regex":"^lrwxrwxrwx .* text\\.txt -> /home/student/Documents/document\\.txt"},"explain":"Link permissions always show rwxrwxrwx; the target's permissions are what count."},{"text":"Make a link `notes.lnk` to `notes.txt`, delete `notes.txt`, then try to read the link.","hints":["ln -s, rm, cat."],"solution":"ln -s notes.txt notes.lnk\nrm notes.txt\ncat notes.lnk","check":{"type":"all","checks":[{"type":"link","path":"/home/student/notes.lnk"},{"type":"last","regex":"No such file or directory"}]},"explain":"The link still exists but points at nothing: a dangling link."},{"text":"Repair it by creating `notes.txt` again with the text `again`, then read the link.","hints":["echo again > notes.txt"],"solution":"echo again > notes.txt\ncat notes.lnk","check":{"type":"last","regex":"^again\\n$"},"explain":"Soft links refer to names, so any new file with that name fixes them."},{"text":"Make `~/logs` a symbolic link to `/var/log`, then list the link's contents.","hints":["ln -s /var/log ~/logs, then ls ~/logs/"],"solution":"ln -s /var/log ~/logs\nls ~/logs/","check":{"type":"all","checks":[{"type":"link","path":"/home/student/logs","target":"/var/log"},{"type":"last","regex":"syslog"}]},"explain":"Soft links to directories are common shortcuts."},{"text":"Try to make a HARD link to the directory `/var/log`.","hints":["ln /var/log ~/loghard"],"solution":"ln /var/log ~/loghard","check":{"type":"last","regex":"hard link not allowed for directory"},"explain":"Hard links to directories could create loops in the tree, so the kernel forbids them."}],"obj":"5.4","lesson":"5.4.1","lessonTitle":"Temporary directories and links","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.4/5.4_01/","part":3,"parts":3},{"id":"T1-a","title":"Is it the gateway?","intro":"A ticket came in: the front desk PC has \"no internet\". Work from the inside out: the local network first, then the way off it. Testing with IP addresses keeps DNS out of the picture until you're ready for it.","setup":{"run":["sudo ip route del default"],"files":[{"path":"~/ticket.txt","data":"Ticket 4471 - front desk PC\nUser says: \"The internet is down, but I can still print.\"\nNetwork notes: printer 192.168.1.50, gateway (router) 192.168.1.1, DNS server 1.1.1.1\n"}]},"commands":["cat","ping","ip"],"tasks":[{"text":"Read the ticket in `ticket.txt`.","hints":["It's a text file in your home directory."],"solution":"cat ticket.txt","check":{"type":"last","regex":"Ticket 4471"},"explain":"Note the gateway and DNS server: you'll need both. Writing down the network details is half of troubleshooting."},{"text":"Test the internet by IP address: ping `1.1.1.1` three times.","hints":["ping's -c option sets how many packets to send."],"solution":"ping -c 3 1.1.1.1","check":{"type":"all","checks":[{"type":"history","regex":"\\bping\\b.*\\b1\\.1\\.1\\.1\\b"},{"type":"last","regex":"Network is unreachable"}]},"explain":"`Network is unreachable` comes from your own computer, not the internet: the kernel has no route that leads to 1.1.1.1. Using an IP address proves this isn't a DNS problem."},{"text":"Now ping the router, `192.168.1.1`, three times.","hints":["Same command, the gateway's address from the ticket."],"solution":"ping -c 3 192.168.1.1","check":{"type":"last","regex":"PING 192\\.168\\.1\\.1[\\s\\S]*, 0% packet loss"},"explain":"The local network works (that's why printing works). Addresses on your own subnet are reached directly; everything else has to go through the gateway, so the gateway setting is the suspect."},{"text":"Show the routing table.","hints":["The ip command has an object for routes."],"solution":"ip route","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*ip\\s+(-4\\s+)?r(o(u(te?)?)?)?(\\s+(show|list))?\\s*$"},{"type":"last","regex":"192\\.168\\.1\\.0/24"}]},"explain":"There's a route for the local subnet (192.168.1.0/24) but no `default via ...` line. The default route is where packets for every other network go. `route -n` and `netstat -r` show the same table on older systems.","mistakes":[{"cmd":"^\\s*(sudo\\s+)?route\\b","out":"route: command not found","say":"`route` comes from the old net-tools package, which isn't installed here (it often isn't on current distributions). The modern equivalent is `ip route`.","try":"route -n"}]},{"text":"Add a default route through the router.","hints":["Changing routes needs root.","ip route add default via GATEWAY"],"solution":"sudo ip route add default via 192.168.1.1","check":{"type":"route","dst":"default","via":"192.168.1.1"},"explain":"Now the kernel knows where to send packets for other networks. A route added with `ip` lasts until reboot: the permanent setting belongs in the network configuration (NetworkManager, netplan), usually handed out by DHCP.","mistakes":[{"cmd":"\\broute\\b.*\\bgw\\b","out":"command not found","say":"`route add default gw ...` is the net-tools syntax. With iproute2 it's `sudo ip route add default via 192.168.1.1`.","try":"sudo route add default gw 192.168.1.1"}]},{"text":"Ping `1.1.1.1` three times again.","hints":["The same test as before."],"solution":"ping -c 3 1.1.1.1","check":{"type":"last","regex":"PING 1\\.1\\.1\\.1[\\s\\S]*3 received"},"explain":"Same test, different result: always re-run the test that failed, so you know the fix fixed it."}],"obj":"4.4","lesson":"T1","lessonTitle":"No internet, but the printer works","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":1,"parts":2,"track":"troubleshoot"},{"id":"T1-b","title":"Is it DNS?","intro":"Another PC on the same ticket: its routing is fine, but the user still says \"nothing loads\". Websites are found by name, so test names this time.","setup":{"files":[{"path":"/etc/resolv.conf","data":"# Generated by NetworkManager\n","owner":"root"}]},"commands":["ping","cat","tee","host"],"tasks":[{"text":"Ping `example.com` three times.","hints":["ping works with names as well as addresses."],"solution":"ping -c 3 example.com","check":{"type":"last","regex":"example\\.com: Temporary failure in name resolution"},"explain":"ping never sent a packet: it couldn't turn the name into an address. That's a name resolution (DNS) failure, not a network one."},{"text":"Prove the network itself works by pinging `1.1.1.1` three times.","hints":["Same test, with an IP address."],"solution":"ping -c 3 1.1.1.1","check":{"type":"last","regex":"PING 1\\.1\\.1\\.1[\\s\\S]*3 received"},"explain":"Addresses work, names don't: classic DNS. Comparing a name with an address is the quickest way to tell the two apart."},{"text":"Show the resolver configuration file, which lists the DNS servers.","hints":["It's in /etc and its name starts with resolv."],"solution":"cat /etc/resolv.conf","check":{"type":"all","checks":[{"type":"history","regex":"\\bcat\\s+/etc/resolv\\.conf\\b"},{"type":"last","regex":"Generated by NetworkManager"}]},"explain":"`/etc/resolv.conf` has no `nameserver` lines, so the system has nobody to ask. Names in `/etc/hosts` still work, because they're looked up locally before DNS."},{"text":"Add the DNS server from the ticket, `1.1.1.1`, to that file.","hints":["The line looks like: nameserver 1.1.1.1","The file belongs to root. sudo applies to a command, not to a >> redirection, so pipe into `sudo tee -a FILE`."],"solution":"echo \"nameserver 1.1.1.1\" | sudo tee -a /etc/resolv.conf","check":{"type":"contains","path":"/etc/resolv.conf","regex":"^nameserver\\s+1\\.1\\.1\\.1\\s*$","flags":"m"},"explain":"`tee -a` appends what it reads to the file, and running tee with sudo is what gives it the right to write there. On many systems NetworkManager or systemd-resolved rewrites this file, so the lasting fix is in their settings.","mistakes":[{"cmd":"sudo\\s+echo.*>>?\\s*/etc/resolv\\.conf","out":"Permission denied","say":"sudo ran `echo` as root, but the `>>` redirection is done by your own shell, which can't write to the file. Pipe into a command that runs as root instead: `echo \"nameserver 1.1.1.1\" | sudo tee -a /etc/resolv.conf`.","try":"sudo echo \"nameserver 1.1.1.1\" >> /etc/resolv.conf"}]},{"text":"Look up `example.com` to prove names work again.","hints":["host asks DNS for a name's addresses."],"solution":"host example.com","check":{"type":"last","regex":"example\\.com has address"},"explain":"host (or dig) talks to the DNS server directly, so it's the clearest proof that name resolution works."}],"obj":"4.4","lesson":"T1","lessonTitle":"No internet, but the printer works","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.4/4.4_01/","part":2,"parts":2,"track":"troubleshoot"},{"id":"T2-a","title":"Permissions along the path","intro":"The intranet page shows **403 Forbidden** since jordan uploaded a new `index.html`. The web server reads files as the user `www-data`, so check what www-data is allowed to do. To read a file, a user needs read permission on the file and execute (search) permission on every directory on the way to it.","setup":{"users":[{"name":"jordan"}],"files":[{"path":"/var/www/html","dir":true,"owner":"root","group":"root","mode":488},{"path":"/var/www/html/index.html","data":"<h1>Intranet</h1>\n<p>Welcome to the staff portal.</p>\n","owner":"jordan","mode":384}]},"commands":["sudo","cat","ls","chmod"],"tasks":[{"text":"Read `/var/www/html/index.html` the way the web server does: as the user `www-data`.","hints":["sudo can run a command as a user other than root.","sudo -u USER COMMAND"],"solution":"sudo -u www-data cat /var/www/html/index.html","check":{"type":"all","checks":[{"type":"history","regex":"sudo\\s+-u\\s+www-data\\s+cat\\s+/var/www/html/index\\.html"},{"type":"last","regex":"Permission denied"}]},"explain":"You've reproduced the problem without a browser. `sudo -u` is the quick way to test permissions as another user."},{"text":"Show the permissions of the directory `/var/www/html` itself, not its contents.","hints":["ls -l lists what's inside a directory. Another option makes it describe the directory."],"solution":"ls -ld /var/www/html","check":{"type":"last","regex":"drwxr-x--- +\\d+ root +root .*/var/www/html"},"explain":"Owner root can do everything, group root can read and enter, and **others** (that includes www-data) get nothing. Without `x` on the directory, nobody else can open anything inside it."},{"text":"Give the directory mode `755` so everyone can enter and list it.","hints":["The directory belongs to root.","sudo chmod MODE DIR"],"solution":"sudo chmod 755 /var/www/html","check":{"type":"perms","path":"/var/www/html","perms":"drwxr-xr-x"},"explain":"755 = rwx for the owner, r-x for group and others: the usual mode for directories that are meant to be read. `chmod o+rx` gives the same result here."},{"text":"Try reading the page as `www-data` again.","hints":["Use the same command as at the start."],"solution":"sudo -u www-data cat /var/www/html/index.html","check":{"type":"all","checks":[{"type":"perms","path":"/var/www/html","perms":"drwxr-xr-x"},{"type":"last","regex":"index\\.html: Permission denied"}]},"explain":"Still denied, but now by the file itself. Permission problems are often layered, so test again after every change."},{"text":"Show the file's permissions and owner.","hints":["ls -l with the file's path."],"solution":"ls -l /var/www/html/index.html","check":{"type":"last","regex":"-rw------- +1 +jordan +jordan"},"explain":"Mode 600 (`rw-------`): only jordan can read it. Files created in a private folder and then copied often keep modes like this."},{"text":"Make the file readable by everyone but writable only by its owner.","hints":["Read for all, write for the owner: in octal that's 6 for the owner and 4 for the rest.","sudo chmod 644 FILE"],"solution":"sudo chmod 644 /var/www/html/index.html","check":{"type":"any","checks":[{"type":"perms","path":"/var/www/html/index.html","perms":"-rw-r--r--"},{"type":"perms","path":"/var/www/html/index.html","perms":"-rw-rw-r--"}]},"explain":"644 (`rw-r--r--`) is the normal mode for web pages and most data files. jordan can still edit it, and everyone else can read it.","mistakes":[{"cmd":"chmod\\s+(0?777|a\\+rwx|ugo\\+rwx)\\b","say":"777 makes the page readable, but also writable and executable by every user. A web page only needs read for others: `644`.","try":"sudo chmod 777 /var/www/html/index.html"}]},{"text":"Prove it's fixed: read the page as `www-data`.","hints":["The same command as the first task."],"solution":"sudo -u www-data cat /var/www/html/index.html","check":{"type":"last","regex":"<h1>Intranet</h1>"},"explain":"Fixed with the smallest change: the directory got `r-x` for others and the file got `r--`, and nothing became world-writable."}],"obj":"5.3","lesson":"T2","lessonTitle":"The intranet page can't be read","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.3/5.3_01/","part":1,"parts":1,"track":"troubleshoot"},{"id":"T3-a","title":"The sticky bit","intro":"A user writes in: \"I have write permission on /tmp, but I can't delete `/tmp/report.csv`. Is the disk broken?\" Reproduce it, explain it, and then build a shared folder that behaves the same way on purpose.","setup":{"users":[{"name":"carol"}],"files":[{"path":"/tmp/report.csv","data":"region,total\nnorth,1200\n","owner":"carol"}]},"commands":["rm","ls","sudo","mkdir","chmod"],"tasks":[{"text":"Try to delete `/tmp/report.csv` without being asked to confirm.","hints":["rm has an option that never prompts."],"solution":"rm -f /tmp/report.csv","check":{"type":"all","checks":[{"type":"exists","path":"/tmp/report.csv"},{"type":"last","regex":"Operation not permitted"}]},"explain":"`Operation not permitted`, even though everyone may write to /tmp. Something more than the usual rwx bits is at work."},{"text":"Show the permissions of `/tmp` itself.","hints":["ls has an option to describe a directory instead of listing it."],"solution":"ls -ld /tmp","check":{"type":"last","regex":"drwxrwxrwt .* /tmp"},"explain":"The `t` in the last position is the **sticky bit**. In a sticky directory, only a file's owner, the directory's owner or root may delete or rename a file, even if everyone can write to the directory."},{"text":"Find out who owns `/tmp/report.csv`.","hints":["ls -l shows the owner."],"solution":"ls -l /tmp/report.csv","check":{"type":"last","regex":"carol .*report\\.csv"},"explain":"It's carol's file, so the sticky bit protects it from you. Nothing is broken: this is what stops users deleting each other's temporary files."},{"text":"Carol confirms the file can go. Delete it as an administrator.","hints":["root is allowed to delete anything."],"solution":"sudo rm /tmp/report.csv","check":{"type":"absent","path":"/tmp/report.csv"},"explain":"root ignores the sticky bit. Check with the owner first: on a shared system, a file in /tmp may be part of something running."},{"text":"Create the directory `/srv/dropbox`, where everyone can add files but can only delete their own.","hints":["Create it with sudo mkdir, then set the mode.","Mode 777 plus the sticky bit: put a 1 in front."],"solution":"sudo mkdir /srv/dropbox\nsudo chmod 1777 /srv/dropbox","check":{"type":"mode","path":"/srv/dropbox","mode":"1777"},"explain":"1777 = the sticky bit (1) plus rwx for everyone (777), exactly like /tmp. `chmod a+rwx,+t` does the same with letters.","mistakes":[{"cmd":"chmod\\s+0?777\\s+/srv/dropbox","say":"777 lets everyone write, but then anyone could also delete anyone's files. Add the sticky bit: `sudo chmod 1777 /srv/dropbox`.","try":"sudo mkdir /srv/dropbox\nsudo chmod 777 /srv/dropbox"}]},{"text":"Check the new directory's permissions.","hints":["The same ls option as for /tmp."],"solution":"ls -ld /srv/dropbox","check":{"type":"last","regex":"drwxrwxrwt .* /srv/dropbox"},"explain":"A lowercase `t` means sticky plus execute for others. A capital `T` would mean sticky without execute, which is rarely what you want."}],"obj":"5.4","lesson":"T3","lessonTitle":"Can't delete a file in /tmp","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.4/5.4_01/","part":1,"parts":1,"track":"troubleshoot"},{"id":"T4-a","title":"Permission, interpreter and PATH","intro":"A colleague wrote `~/bin/backup.sh` to archive your Documents folder, but says \"it doesn't work\". Get it running, one error at a time. Read each error message carefully: they're different, and each one points at the cause.","setup":{"files":[{"path":"~/bin/backup.sh","data":"#!/bin/bsh\n# Back up ~/Documents into ~/backups/docs.tar.gz\nmkdir -p ~/backups\ntar -czf ~/backups/docs.tar.gz -C ~ Documents\necho \"Backup done\"\n"},{"path":"~/Documents/budget.ods","data":"spreadsheet\n"},{"path":"~/Documents/notes.txt","data":"meeting notes\n"}]},"commands":["ls","chmod","head","sed","echo","export"],"tasks":[{"text":"Run the script by its path.","hints":["Type the path to the script as the command."],"solution":"~/bin/backup.sh","check":{"type":"last","regex":"backup\\.sh: Permission denied"},"explain":"To run a file as a command, you need execute permission on it."},{"text":"Check the script's permissions.","hints":["ls -l with the path."],"solution":"ls -l ~/bin/backup.sh","check":{"type":"last","regex":"-rw-r--r-- .*backup\\.sh"},"explain":"No `x` anywhere. New files are created without execute permission (the umask leaves it out), so scripts need it added."},{"text":"Make the script executable for its owner (you).","hints":["chmod with symbolic mode: who, +, what."],"solution":"chmod u+x ~/bin/backup.sh","check":{"type":"any","checks":[{"type":"perms","path":"/home/student/bin/backup.sh","perms":"-rwxr--r--"},{"type":"perms","path":"/home/student/bin/backup.sh","perms":"-rwxr-xr-x"},{"type":"perms","path":"/home/student/bin/backup.sh","perms":"-rwxr-xr--"},{"type":"perms","path":"/home/student/bin/backup.sh","perms":"-rwx------"},{"type":"perms","path":"/home/student/bin/backup.sh","perms":"-rwxrw-r--"}]},"explain":"`u+x` adds execute for the owner only. `chmod +x` would add it for everyone, which is also fine for most scripts."},{"text":"Run it again.","hints":["Same command as the first task."],"solution":"~/bin/backup.sh","check":{"type":"last","regex":"bad interpreter"},"explain":"A new error: `bad interpreter: No such file or directory`. The script is executable now, but the program named on its first line doesn't exist."},{"text":"Show only the first line of the script.","hints":["head can limit how many lines it prints."],"solution":"head -n 1 ~/bin/backup.sh","check":{"type":"all","checks":[{"type":"history","regex":"\\bhead\\b"},{"type":"last","regex":"^#!/bin/bsh\\n$"}]},"explain":"The first line, `#!` followed by a path, is the **shebang**: the kernel runs that program and gives it the script. `/bin/bsh` is a typo."},{"text":"Fix the typo so the first line is `#!/bin/bash`.","hints":["sed -i edits a file in place.","sed -i '1s/bsh/bash/' FILE changes the first match on line 1."],"solution":"sed -i '1s/bsh/bash/' ~/bin/backup.sh","check":{"type":"contains","path":"/home/student/bin/backup.sh","regex":"^#!/bin/bash\n"},"explain":"`1s/old/new/` limits the substitution to line 1. Opening the file in nano or vi works just as well."},{"text":"Run the script, then print its exit status.","hints":["The special variable $? holds the exit status of the last command."],"solution":"~/bin/backup.sh\necho $?","check":{"type":"all","checks":[{"type":"exists","path":"/home/student/backups/docs.tar.gz"},{"type":"history","regex":"echo\\s+\\$\\?"},{"type":"last","regex":"(^|\\n)0\\n$"}]},"explain":"Exit status 0 means success (that's the name of this app). Scripts that call other programs should check `$?`, or use `&&`, before carrying on."},{"text":"Add `~/bin` to the end of your PATH for this session, then run the script by its name alone.","hints":["Keep what's already in PATH and add :$HOME/bin after it.","export PATH=\"$PATH:$HOME/bin\""],"solution":"export PATH=\"$PATH:$HOME/bin\"\nbackup.sh","check":{"type":"all","checks":[{"type":"var","name":"PATH","regex":"(^|:)/home/student/bin/?(:|$)"},{"type":"var","name":"PATH","regex":"/usr/bin"},{"type":"history","regex":"^\\s*backup\\.sh\\s*$"},{"type":"last","regex":"Backup done"}]},"explain":"The shell looks for commands only in the directories listed in PATH. To keep the change, add the same line to `~/.bashrc` (many distributions' `~/.profile` already adds `~/bin` if it exists when you log in).","mistakes":[{"cmd":"PATH=[\\\"']?(\\$HOME|~|/home/student)/bin/?[\\\"']?\\s*$","say":"That replaced PATH instead of extending it, so commands like ls and tar can't be found any more. Keep the old value in front: `export PATH=\"$PATH:$HOME/bin\"`. (Fix it now with `export PATH=/usr/bin:/bin:$HOME/bin`.)","try":"export PATH=$HOME/bin"}]}],"obj":"3.3","lesson":"T4","lessonTitle":"The backup script won't run","url":"https://learning.lpi.org/en/learning-materials/010-160/3/3.3/3.3_01/","part":1,"parts":1,"track":"troubleshoot"},{"id":"T5-a","title":"Group membership","intro":"devon moved from sales to finance this week. He can open `/srv/finance` in the file manager but can't save anything there. maria, who has been in finance for years, has no problem.","setup":{"groups":[{"name":"finance","gid":2100},{"name":"sales","gid":2200}],"users":[{"name":"maria","groups":["finance"]},{"name":"devon","groups":["sales"]}],"files":[{"path":"/srv/finance","dir":true,"owner":"root","group":"finance","mode":1528},{"path":"/srv/finance/budget.ods","data":"spreadsheet\n","owner":"maria","group":"finance","mode":432}]},"commands":["sudo","touch","ls","groups","usermod"],"tasks":[{"text":"Reproduce the problem: as `devon`, create the file `/srv/finance/q4.txt`.","hints":["sudo -u USER runs a command as that user.","touch creates an empty file."],"solution":"sudo -u devon touch /srv/finance/q4.txt","check":{"type":"all","checks":[{"type":"absent","path":"/srv/finance/q4.txt"},{"type":"last","regex":"Permission denied"}]},"explain":"Reproducing the problem as the affected user is faster and more reliable than asking them to try again."},{"text":"Show the permissions of `/srv/finance` itself.","hints":["ls has an option to describe a directory instead of listing it."],"solution":"ls -ld /srv/finance","check":{"type":"last","regex":"drwxrws--- .*root +finance .*/srv/finance"},"explain":"Owner root, group `finance`, and others get nothing. The `s` where the group's `x` would be is the **setgid** bit: files created inside get the directory's group, not the creator's."},{"text":"List the groups `devon` belongs to.","hints":["groups (or id) accepts a user name."],"solution":"groups devon","check":{"type":"all","checks":[{"type":"history","regex":"\\b(groups|id)\\s+(-\\w+\\s+)?devon\\b"},{"type":"last","regex":"sales"}]},"explain":"devon is still only in `sales`. Moving departments changed his job, not his account."},{"text":"Add devon to `finance` without taking him out of `sales` (he's still finishing a sales project).","hints":["usermod changes accounts and needs root.","-G sets the supplementary groups; -a makes it add to them instead of replacing them."],"solution":"sudo usermod -aG finance devon","check":{"type":"user","name":"devon","groups":["finance","sales"]},"explain":"`-aG` appends. On the exam and in real life, `-G` without `-a` replaces the whole list, a common way to lock someone out of everything else. `gpasswd -a devon finance` would also work.","mistakes":[{"cmd":"usermod\\s+-G\\s","say":"Without `-a`, `usermod -G` replaces devon's supplementary groups, so he just lost `sales`. Put both back with `sudo usermod -aG sales,finance devon`, and use `-aG` from now on.","try":"sudo usermod -G finance devon"}]},{"text":"Try creating `/srv/finance/q4.txt` as devon again.","hints":["The same command as the first task."],"solution":"sudo -u devon touch /srv/finance/q4.txt","check":{"type":"exists","path":"/srv/finance/q4.txt"},"explain":"It works. On a real desktop, devon has to log out and back in first: group membership is read at login."},{"text":"Check which group the new file belongs to. You're not in finance, so you'll need root to look inside.","hints":["sudo ls -l with the file's path."],"solution":"sudo ls -l /srv/finance/q4.txt","check":{"type":"last","regex":"devon +finance .*q4\\.txt"},"explain":"Group `finance`, not devon's own group: that's the setgid directory at work, so maria can open devon's files too."}],"obj":"5.2","lesson":"T5","lessonTitle":"The new hire can't save to the shared folder","url":"https://learning.lpi.org/en/learning-materials/010-160/5/5.2/5.2_01/","part":1,"parts":1,"track":"troubleshoot"},{"id":"T6-a","title":"Find it, read its log, stop it","intro":"Everyone says the server got slow this morning. Find out what's using it, why, and stop it, but read before you kill.","setup":{"users":[{"name":"maria"}],"procs":[{"pid":4242,"user":"maria","cmd":"/usr/local/bin/report-gen --all","cpu":98.5,"stat":"R","time":"47:12","ignoresTerm":true}],"files":[{"path":"/var/log/report-gen.log","data":"2026-10-10 05:59:58 report-gen started (--all)\n2026-10-10 06:00:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:00:32 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:01:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:01:32 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:02:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:02:32 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:03:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:03:32 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:04:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:04:32 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:05:02 ERROR connection to db.internal:5432 timed out, retrying\n2026-10-10 06:05:32 ERROR connection to db.internal:5432 timed out, retrying\n","owner":"maria"}]},"commands":["top","free","ps","tail","kill"],"tasks":[{"text":"See what's using the CPU right now.","hints":["The live process monitor sorts by CPU use."],"solution":"top","check":{"type":"last","regex":"4242 maria .*report-gen"},"explain":"One process, `report-gen`, owned by maria, is using about 99% of a CPU core. top's header also shows the load average and memory."},{"text":"Check memory, in human-readable units.","hints":["free has an option for units like Gi and Mi."],"solution":"free -h","check":{"type":"all","checks":[{"type":"history","regex":"^\\s*free\\b"},{"type":"last","regex":"Mem:"}]},"explain":"Plenty is `available` and swap is unused, so memory isn't the problem: this is all CPU."},{"text":"Show the full command line of process 4242.","hints":["ps -f shows full command lines; -p selects a PID."],"solution":"ps -fp 4242","check":{"type":"last","regex":"/usr/local/bin/report-gen --all"},"explain":"Full format shows the owner, parent PID, start time, CPU time used (`TIME`) and the whole command with its options."},{"text":"Read the last lines of its log, `/var/log/report-gen.log`.","hints":["tail shows the end of a file."],"solution":"tail /var/log/report-gen.log","check":{"type":"last","regex":"retrying"},"explain":"It can't reach its database and retries in a tight loop. That's the real fault: killing it only stops the symptom, so tell maria what the log says."},{"text":"maria agrees it can be stopped. Ask it to exit politely (the default signal).","hints":["It's maria's process, so you need root.","kill without a signal option sends SIGTERM (15)."],"solution":"sudo kill 4242","check":{"type":"all","checks":[{"type":"history","regex":"\\bsudo\\s+kill\\s+(-15\\s+|-TERM\\s+|-SIGTERM\\s+|-s\\s+(15|TERM)\\s+)?4242\\b"},{"type":"proc","cmd":"report-gen"}]},"explain":"SIGTERM asks a program to clean up and exit. A program can catch it, and a stuck one may ignore it."},{"text":"Check whether process 4242 is still running.","hints":["ps -p PID"],"solution":"ps -p 4242","check":{"type":"all","checks":[{"type":"history","regex":"\\bsudo\\s+kill\\b"},{"type":"proc","cmd":"report-gen"},{"type":"last","regex":"4242 .*report-gen"}]},"explain":"Still there: it ignored SIGTERM. Always check after sending a signal instead of assuming it worked."},{"text":"Force it to stop.","hints":["SIGKILL (9) can't be caught or ignored.","sudo kill -9 PID"],"solution":"sudo kill -9 4242","check":{"type":"noproc","cmd":"report-gen"},"explain":"SIGKILL ends the process immediately, with no chance to save anything or clean up, so use it only after SIGTERM fails."},{"text":"Confirm with top that the CPU is free again.","hints":["The same command as the first task."],"solution":"top","check":{"type":"all","checks":[{"type":"noproc","cmd":"report-gen"},{"type":"history","regex":"^\\s*top\\b"},{"type":"last","regex":"load average"},{"type":"not","check":{"type":"last","regex":"report-gen"}}]},"explain":"report-gen is gone from the list. The load average will fall over the next few minutes, since it's an average."}],"obj":"4.3","lesson":"T6","lessonTitle":"The server is slow","url":"https://learning.lpi.org/en/learning-materials/010-160/4/4.3/4.3_02/","part":1,"parts":1,"track":"troubleshoot"}];
